INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'History', 'Unit 4', 'Molarum Grade 10 — History Unit 4: Society and Politics in the Age of World Wars 1914–1945', 'Source-grounded Molarum Grade 10 History questions for Unit 4: Society and Politics in the Age of World Wars 1914–1945.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('a599b0b2-d361-4807-8aa7-066f950cec54'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which three states formed the Triple Alliance when it was originally created?', 'Germany, Austria-Hungary, and Italy', 'The textbook identifies Germany, Austria-Hungary, and Italy as the original Triple Alliance members.', 0),('53279197-3797-4d3b-8e6d-b66ba047a514'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Who assassinated Archduke Franz Ferdinand in Sarajevo?', 'Gavrilo Princip', 'The source identifies Gavrilo Princip as the Serbian nationalist who assassinated Franz Ferdinand.', 1),('ba75c592-bde1-461d-8af8-f37a46462f1f'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Under the Schlieffen Plan, Germany proposed attacking France through which country?', 'Belgium', 'The Schlieffen Plan called for an attack on France through Belgium.', 2),('bcc72d39-cc82-401d-8fcf-a57bf07e8e63'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which battle halted the German advance in September 1914?', 'Battle of the Marne', 'The German advance was forced back at the Battle of the Marne in September 1914.', 3),('1a6c01a9-1b9a-47d7-886f-de3b6bf900a1'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What type of German campaign helped lead the United States to enter World War I?', 'Unrestricted submarine campaign', 'Germany’s unrestricted submarine campaign was one factor that led the United States to declare war.', 4),('dd4a2e85-2e00-445b-8ea2-8e86a137bd46'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which technology was used during World War I according to the textbook?', 'Poisonous gas', 'The source lists poisonous gases among the technologies used in World War I.', 5),('ed197106-7918-452a-8ef8-5611d9bb9777'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which imperial dynasty collapsed in Russia after World War I?', 'Romanovs', 'The textbook lists the Romanovs of Russia among the dynasties that collapsed after the war.', 6),('f29e2bd5-1eb2-44bd-86eb-70e1ebe5fb86'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which political group was led by Lenin?', 'Bolsheviks', 'The source identifies Lenin as leader of the Bolsheviks.', 7),('69c73301-eacd-4748-884f-9ee2d67e4a94'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What form of rule ended when Tsar Nicholas II was deposed in February 1917?', 'Romanov dynasty rule', 'Nicholas II’s deposition ended the rule of the Romanov Dynasty.', 8),('9c7fba2f-57ae-4acc-827b-a4eb11d81ea6'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What were the Soviets described as in the textbook?', 'Councils or coordinating bodies', 'The textbook defines Soviets as councils or coordinating bodies.', 9),('820336fb-6a6f-4de5-8324-721344aa4bb7'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Where was the League of Nations headquartered?', 'Geneva, Switzerland', 'The source says the League of Nations was headquartered in Geneva, Switzerland.', 10),('12935b81-c017-415d-80ac-2d49d4d171ec'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which United States president proposed forming the League of Nations?', 'Woodrow Wilson', 'The textbook states that President Woodrow Wilson proposed the League of Nations.', 11),('16a1dbc5-90bf-4110-86b0-f2a3b34f12c2'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What event began the Great Depression according to the textbook?', 'The Wall Street stock market crash', 'The source dates the beginning of the Great Depression to the Wall Street stock market crash of October 1929.', 12),('3c1c937a-817f-49c7-84f2-9daf311e6ac9'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'In which country was a Fascist state established in 1922?', 'Italy', 'The textbook says a Fascist state was established in Italy in 1922.', 13),('5591f02c-7525-47ff-8ce1-6157075cb0c4'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which dispute did the League of Nations peacefully negotiate in 1926?', 'The Mosul dispute between Iraq and Turkey', 'The League negotiated a peaceful outcome to the Iraq–Turkey conflict over Mosul in 1926.', 14),('ef28aec5-4a29-41d6-89db-fa16f5cf3802'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What did Mussolini do to Italy’s political parties as totalitarianism rose?', 'He dissolved all parties except his own', 'The source says Mussolini dissolved all political parties except his own.', 15),('942529c5-e937-49ca-8686-16668c5018e9'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What was the name of Hitler’s autobiography written during imprisonment?', 'Mein Kampf', 'The textbook says Hitler wrote Mein Kampf during imprisonment and it was published in 1926.', 16),('7e517fa3-64af-4675-8c49-9c11849b8f5c'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What policy did Britain and France follow by allowing some territorial seizures by Fascist states?', 'Appeasement', 'Britain and France followed appeasement in an effort to avoid another world war.', 17),('529a1bb8-9c63-429f-8023-eccba6f0e76e'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'What did the Germans call their 1939 campaign in Poland?', 'Blitzkrieg', 'The Germans called their Polish campaign Blitzkrieg, meaning lightning war.', 18),('e6c97449-69e9-47f3-8f3a-ea87e4d00878'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'multiple_choice', 'Which event brought the United States into the Second World War?', 'Japan’s attack on Pearl Harbor', 'After Japan attacked Pearl Harbor in December 1941, the United States declared war on Japan.', 19),('dc3f4024-d563-48c9-8761-9c0372438d95'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'true_false', 'Growing rivalry and mistrust contributed to the formation of military alliances before World War I.', 'True', 'The source says growing rivalries and mutual mistrust led to several military alliances among the Great Powers.', 20),('e3ec2a51-da23-466d-833a-0c58326da5c9'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'true_false', 'The New Economic Policy restored smaller enterprises to their owners and allowed peasants to sell grain for profit.', 'True', 'The NEP restored smaller enterprises, permitted grain sales for profit, and revived commerce.', 21),('b57a5e57-54dd-42b9-80c7-a25a63cb2715'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'true_false', 'The United States became a member of the League of Nations after its formation.', 'False', 'The U.S. Congress resisted membership, and the United States did not join the League.', 22),('e5c047f7-7008-4e32-8dd9-06a8d9cc2369'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'true_false', 'The United Nations Organization replaced the League of Nations after World War II.', 'True', 'The source says the urge to maintain world peace gave birth to the UN, which replaced the League.', 23),('e438223b-0d1e-4ae2-8197-5da64ab0b7b4'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'Name one root cause of World War I identified in the textbook.', 'Mutual defense alliances, imperialism, militarism, or nationalism.', 'The textbook identifies these as major causes that set the stage for World War I.', 24),('4c1eea52-a8a6-4ba8-8cc1-96a16edf7333'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'State one consequence of the Treaty of Versailles for Germany described in the textbook.', 'Germany faced military restrictions, was assigned responsibility for the war, had to pay reparations, or lost substantial territory.', 'The source lists military restrictions, war responsibility, reparations, and territorial losses as effects on Germany.', 25),('82995293-45f7-425a-8ed2-aa518cc87050'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'Give one factor that weakened the Provisional Government in 1917.', 'It failed to end food shortages or bring the war to an end.', 'The textbook says the Provisional Government lost public support because it did not resolve food shortages or end the war.', 26),('b82edc1e-43c6-4d9a-8b5d-f6bf108d111c'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'State one principal goal of the League of Nations.', 'Preventing wars through collective security and disarmament, or settling disputes through negotiation and arbitration.', 'The Covenant’s goals included collective security, disarmament, negotiation, and arbitration.', 27),('1c21ccde-7bc6-4e03-88ff-ab9ef2713e84'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'Give one effect of the Great Depression stated in the textbook.', 'Falling income, tax revenue, profits, prices, international trade, industrial output, or employment; high unemployment; bank failures; or falling crop prices.', 'The source describes severe declines in trade, employment, income, prices, and banking stability.', 28),('e24fce12-57b1-4a22-86d3-6d3fdfa6dc9b'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'Give one postwar condition in Italy that favoured the rise of Fascism.', 'Disappointment with the Treaty of Versailles, economic collapse, scarcity of natural resources, labour unrest, unemployment, or fear of communism.', 'The source links Fascism’s rise to postwar disappointment and severe political, social, and economic problems.', 29),('6ae0bac3-f660-4f5a-885a-bed12f3f8dbc'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'Name one major Allied power listed for World War II.', 'France, Britain, the United States, or the Soviet Union.', 'The source identifies France, Britain, the USA, and the USSR as the main Allied Powers.', 30),('f3647df0-1058-459d-8997-f9ff18516873'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'State one major effect of World War II listed in the textbook.', 'Immense human and material loss, hastened decolonization, emergence of the USA and USSR as superpowers, the Cold War, or formation of the UNO.', 'The textbook lists these as far-reaching effects of World War II.', 31),('84db4ab7-c50f-4f3c-8778-1f7c418bff5c'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did Austria-Hungary declare war on Serbia?', '1914', 'Austria-Hungary declared war on Serbia on 28 July 1914.', 32),('390bb747-b42d-4edb-8fab-7d77f2acbef6'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did the United States declare war on Germany?', '1917', 'The United States declared war on Germany on 6 April 1917.', 33),('fe6003bc-25a0-4f52-81c2-ac7a8d778f60'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did the Bolsheviks sign the Treaty of Brest-Litovsk and formally withdraw Russia from World War I?', '1918', 'The source says Russia formally withdrew after signing the Treaty of Brest-Litovsk with Germany in 1918.', 34),('d34014ea-1314-426c-862d-7edeef3436a2'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year was the League of Nations founded?', '1920', 'The League was founded on 10 January 1920 following the Paris Peace Conference.', 35),('e00416ec-120d-439f-89f8-f46a8624bf8c'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did the Wall Street crash that began the Great Depression occur?', '1929', 'The source dates the Wall Street stock market crash to October 1929.', 36),('68e3504a-b77e-4e8b-8b55-804a925df6c8'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did the Nazis come to power in Germany?', '1933', 'The textbook says the Nazis came to power in Germany in 1933.', 37),('3d15495c-72d8-46f9-84bd-adae9fe2d216'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did Germany invade Poland, marking the beginning of World War II?', '1939', 'Germany invaded Poland on 1 September 1939, marking the beginning of World War II.', 38),('f0e109dd-db70-429e-8607-6c89af278c8d'::uuid, 'a42d2135-2e89-4818-8a71-49cf513c04bd'::uuid, 'fill_blank', 'In what year did Japan unconditionally surrender at the end of World War II?', '1945', 'Japan unconditionally surrendered after the United States dropped atomic bombs in August 1945 and occupied Tokyo in September.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('e04c6c17-3600-43b3-8373-628d2e795199'::uuid, 'a599b0b2-d361-4807-8aa7-066f950cec54'::uuid, 'Germany, Austria-Hungary, and Italy', TRUE, 0),('24da2ad0-d8c9-426a-867f-4919b0e1069a'::uuid, 'a599b0b2-d361-4807-8aa7-066f950cec54'::uuid, 'Britain, France, and Russia', FALSE, 1),('489bcd6c-ae2b-47d9-86e0-18093f8b1022'::uuid, 'a599b0b2-d361-4807-8aa7-066f950cec54'::uuid, 'Germany, Russia, and Japan', FALSE, 2),('05aa48d2-050d-422c-8faf-3c7706d3137b'::uuid, 'a599b0b2-d361-4807-8aa7-066f950cec54'::uuid, 'Italy, France, and the United States', FALSE, 3),('6a8ab897-2ede-4ebe-8dd5-689e60d0e31f'::uuid, '53279197-3797-4d3b-8e6d-b66ba047a514'::uuid, 'Gavrilo Princip', TRUE, 0),('8a30b502-d0c1-4235-839a-4448228e7c19'::uuid, '53279197-3797-4d3b-8e6d-b66ba047a514'::uuid, 'Benito Mussolini', FALSE, 1),('e6f49d92-de92-4fc6-8fb0-7214d5d7de21'::uuid, '53279197-3797-4d3b-8e6d-b66ba047a514'::uuid, 'Arthur Zimmermann', FALSE, 2),('ad31a2eb-f00f-4f3f-8afc-14580521b059'::uuid, '53279197-3797-4d3b-8e6d-b66ba047a514'::uuid, 'Alfred von Schlieffen', FALSE, 3),('dde5fbff-3f4c-49c7-8bee-0bb14fa3aff8'::uuid, 'ba75c592-bde1-461d-8af8-f37a46462f1f'::uuid, 'Belgium', TRUE, 0),('d8ee5f4b-0626-4f60-816b-fe7242f96643'::uuid, 'ba75c592-bde1-461d-8af8-f37a46462f1f'::uuid, 'Switzerland', FALSE, 1),('3ec1d970-880e-4788-8dc7-95d7aa16a673'::uuid, 'ba75c592-bde1-461d-8af8-f37a46462f1f'::uuid, 'Spain', FALSE, 2),('4e9d6e12-cfe6-4606-898e-bb5292e30da4'::uuid, 'ba75c592-bde1-461d-8af8-f37a46462f1f'::uuid, 'Denmark', FALSE, 3),('6a3496b6-35f5-4831-84ba-232083b1a7cb'::uuid, 'bcc72d39-cc82-401d-8fcf-a57bf07e8e63'::uuid, 'Battle of the Marne', TRUE, 0),('f5c43dc4-d7e6-4131-85ea-f90228e04a98'::uuid, 'bcc72d39-cc82-401d-8fcf-a57bf07e8e63'::uuid, 'Battle of Stalingrad', FALSE, 1),('e476ca82-a871-4724-8bf8-99619c703c97'::uuid, 'bcc72d39-cc82-401d-8fcf-a57bf07e8e63'::uuid, 'Battle of Kursk', FALSE, 2),('d7db9c6f-2198-4c46-81e1-c1e8da