'f29e2bd5-1eb2-44bd-86eb-70e1ebe5fb86'::uuid, 'White Armies', FALSE, 3),('844af151-06f5-489a-8e1f-ac859e8466ee'::uuid, '69c73301-eacd-4748-884f-9ee2d67e4a94'::uuid, 'Romanov dynasty rule', TRUE, 0),('6d9222c7-0c7f-454f-8fc7-bf2db1eba1ba'::uuid, '69c73301-eacd-4748-884f-9ee2d67e4a94'::uuid, 'Fascist rule', FALSE, 1),('b22d5b82-94a5-46f6-8ac8-5abd2d3452b4'::uuid, '69c73301-eacd-4748-884f-9ee2d67e4a94'::uuid, 'League of Nations rule', FALSE, 2),('c063056c-c1eb-427e-83d4-f6409ce9a3a1'::uuid, '69c73301-eacd-4748-884f-9ee2d67e4a94'::uuid, 'Japanese militarism', FALSE, 3),('7c10476d-5418-4eb7-8208-fdc993130e9f'::uuid, '9c7fba2f-57ae-4acc-827b-a4eb11d81ea6'::uuid, 'Councils or coordinating bodies', TRUE, 0),('b429e6a5-872d-4c74-8668-6f698794b73f'::uuid, '9c7fba2f-57ae-4acc-827b-a4eb11d81ea6'::uuid, 'Secret police units', FALSE, 1),('762e1d6a-505e-4a05-862b-778497a3ca3e'::uuid, '9c7fba2f-57ae-4acc-827b-a4eb11d81ea6'::uuid, 'Imperial armies', FALSE, 2),('8ec864ce-1c59-4044-8803-3033a80281c8'::uuid, '9c7fba2f-57ae-4acc-827b-a4eb11d81ea6'::uuid, 'Private banks', FALSE, 3),('01bb0c91-6c0c-4efb-8a18-d4834d8f16b2'::uuid, '820336fb-6a6f-4de5-8324-721344aa4bb7'::uuid, 'Geneva, Switzerland', TRUE, 0),('f5f05570-91e0-44eb-8906-e1d2ab45b58c'::uuid, '820336fb-6a6f-4de5-8324-721344aa4bb7'::uuid, 'Paris, France', FALSE, 1),('ebf9c6a9-057c-43fc-8825-ea8ec54c893a'::uuid, '820336fb-6a6f-4de5-8324-721344aa4bb7'::uuid, 'London, Britain', FALSE, 2),('d0b5fcc5-ee0b-4d67-8159-0b28b6e12124'::uuid, '820336fb-6a6f-4de5-8324-721344aa4bb7'::uuid, 'Rome, Italy', FALSE, 3),('92620c37-32ef-4703-83aa-01e119699078'::uuid, '12935b81-c017-415d-80ac-2d49d4d171ec'::uuid, 'Woodrow Wilson', TRUE, 0),('1047a802-a687-4b83-8e79-27ca6f790a8c'::uuid, '12935b81-c017-415d-80ac-2d49d4d171ec'::uuid, 'Franklin Roosevelt', FALSE, 1),('3d73f623-7cfc-4eac-8440-b77c412e759f'::uuid, '12935b81-c017-415d-80ac-2d49d4d171ec'::uuid, 'Abraham Lincoln', FALSE, 2),('20f49698-91da-4595-8966-769fc9346ed9'::uuid, '12935b81-c017-415d-80ac