INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'Mathematics', 'Unit 1', 'Molarum Grade 10 — Mathematics Unit 1: Relations and Functions', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 1: Relations and Functions.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('5af3c626-2c4c-4ef3-889a-08231c848601'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Which of the following best matches the textbook definition of a relation?', 'A set of ordered pairs.', 'The excerpt defines a relation as a set of ordered pairs (Definition 1.1).', 0),('34fea43f-0f9e-41ef-8cd1-66c1945a6087'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'For the point P(3,2) in the text, which terms correctly name 3 and 2?', '3 is the abscissa and 2 is the ordinate.', 'The excerpt explains the first coordinate is the abscissa and the second is the ordinate (section 1.1.2, example P(3,2)).', 1),('bb199ac5-9d90-4867-81c5-d198c558cbac'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'What are the coordinates of the origin as given in the text?', '(0, 0)', 'The excerpt states the origin has coordinates (0, 0) (section 1.1.2).', 2),('f43ab72f-f701-4eab-8f5b-08f59ced5546'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'According to the textbook convention, which axis is usually horizontal and oriented to the right?', 'The x-axis', 'The excerpt states the first axis is usually horizontal and oriented to the right and is called the x-axis (section 1.1.2).', 3),('be7e806e-90ca-478c-87d8-c54f584c2b29'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'The sequence 2, 4, 6, 8, 10, ... is classified in the text as which type of pattern?', 'Arithmetic pattern', 'The excerpt explains an arithmetic (algebraic) pattern is based on addition or subtraction, and 2,4,6,8... is given as an even-number arithmetic pattern (section 1.1.1).', 4),('e146ed63-a39b-4fed-82e0-002da29430f3'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'What is the next number in the sequence 1, 3, 5, 7, 9, ___ shown in Activity 1.1?', '11', 'Activity 1.1 shows an odd-number sequence increasing by 2, so the next term after 9 is 11 (section 1.1.1).', 5),('ede2c5cb-9453-4ea1-8e13-b236722c8392'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'What is the domain of the relation with ordered pairs (−2,1), (−1,0), (0,0), (4,2), (3,5) as given in Example 1?', '{−2, −1, 0, 3, 4}', 'Example 1 lists those first components and identifies the domain as −2, −1, 0, 4 and 3 (section ''Example 1'' under Domain and range).', 6),('35abf2a7-d42e-4246-8735-f828bc64c92c'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Which statement matches the textbook definition of a function?', 'No two distinct ordered pairs have the same first element.', 'Definition 1.3 in the excerpt states a function is a relation in which no two distinct ordered pairs have the same first element.', 7),('0151ded4-e6ac-4c64-8194-d5988679df02'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Given the list (2,4), (4,3), (3,9), (18,−3), (9,3), (7,7), (3,12), (6,18), (30,5), which ordered pairs does the excerpt state belong to the relation ''y is a multiple of x'' (Example 2)?', '(2,4), (3,9), (7,7), (3,12), (6,18)', 'Example 2 lists those five ordered pairs as belonging to the relation where the second is a multiple of the first (section ''Example 2'').', 8),('ed2770e6-71de-4c94-81be-67b8d9d842e4'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Which sentence correctly states the Vertical Line Test as given in the text?', 'A numerical relation is a function iff no vertical line intersects its graph in more than one point.', 'The excerpt explicitly states a numerical relation is a function iff no vertical line intersects the graph in more than one point (Vertical Line Test note).', 9),('f40c70a6-8669-42a0-8cd3-1eafb3b62f7f'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Why does the excerpt show f(x)=3x+5 is one-to-one?', 'Because f(a)=f(b) leads to 3a+5=3b+5 and so a=b.', 'Example 1 under One-to-one demonstrates f( )=3 +5 is one-to-one by showing f(1)=f(2) implies 3·1+5=3·2+5, hence 1=2, so in general f(a)=f(b) ⇒ a=b (section 1.2.3).', 10),('a607db74-919b-4b87-86a5-5200fdbf570a'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'According to the textbook, which statement about f(x)=2 is correct?', 'f(x)=2 is a constant function.', 'The excerpt states when a=0 in f(x)=ax+b the function reduces to f(x)=b which is called a constant function, and example 3 shows f(x)=2 as a constant function (section ''Graph of linear function'').', 11),('cff4dcfd-7309-4302-88c9-72847d62a004'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'For the linear function f(x)=3x−6 stated in the examples, what are the x- and y-intercepts?', 'x-intercept (2,0); y-intercept (0,−6)', 'The excerpt finds the x-intercept by setting f(x)=0 giving x=2, and the y-intercept by setting x=0 giving f(0)=−6 (section ''Example 1'' under Slope and intercept).', 12),('8e773961-a185-482e-81fd-9a930a04d165'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'What is the vertex of the quadratic function f(x)=x^2+6x+11 after completing the square as shown in the text?', '(−3,2)', 'The excerpt completes the square: x^2+6x+11 = (x+3)^2 + 2, so the vertex is (−3,2) (section ''Example 1'' in completing the square).', 13),('eb699467-c9fa-4480-8522-ac431772d93e'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'For the curve y=(x−3)^2+2 discussed in the text, what is its y-intercept?', '11', 'Setting x=0 gives y=(0−3)^2+2=9+2=11, so the y-intercept is 11 as shown in the example (section ''Example 1'' under ''Graph of y=a(x−k)^2 + c'').', 14),('41ad4876-da82-47e8-812e-9fe6b03ed79e'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'What is the maximum value of f(x)=−(x−3)^2+1 as found in the text?', '1', 'The excerpt writes f(x)=−(x−3)^2+1 and notes the vertex (3,1) gives the maximum value 1 because the parabola opens downward (Example 2 under Minimum and Maximum values).', 15),('50389e57-cf94-4441-8cc6-a82646c3ee7b'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Which are the solutions (x values) of x^2−4=0 as obtained graphically in the examples?', 'x=−2 and x=2', 'The graphical solution example for x^2−4=0 shows the graph crosses the x-axis at −2 and 2, giving those two solutions (section ''Example 1'' under ''Graphical method'').', 16),('1f9fbfb1-3f8c-484d-80bf-a3837df9528a'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'From the worked example, the solution set of x^2−6x+8<0 is which interval?', '(2,4)', 'The example solving x^2−6x+8<0 finds the parabola is below the x-axis between the roots x=2 and x=4, so the solution is (2,4) (section ''Example 1'' under ''Graphical method of solving quadratic inequalities'').', 17),('4f852bfe-f815-4109-88ef-9b61b9be6abe'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'What is the domain of f(x)=√(x−2) as shown in the excerpt?', 'x ≥ 2', 'The excerpt states for f(x)=√(x−2) the expression under the radical must be non-negative, so x−2 ≥ 0 and domain is x ≥ 2 (Example under ''If f(x)=√(x−2)'').', 18),('890e1566-c888-4016-890a-9576c68109c0'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'multiple_choice', 'Using examples in the text, (f+g)(x) is defined as which expression when f and g have overlapping domains?', 'f(x)+g(x)', 'The excerpt defines the sum (f+g)(x)=f(x)+g(x) for x common to both domains (section ''Combination of functions, Sum of functions'').', 19),('088ea305-529c-47ea-8df2-8307dd2b4e9c'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'true_false', 'A relation establishes pairing between objects and order is important.', 'True', 'The excerpt notes in the ''Note'' under Activity 1.3 that a relation establishes pairing and order is important (section 1.1.3).', 20),('1640122b-e2e7-4408-8e55-465064f7307f'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'true_false', 'A function can have two distinct ordered pairs with the same first element provided the second elements are equal.', 'True', 'The excerpt explains repeated ordered pairs with the same first element are acceptable if they associate with the same second element, so the relation remains a function (Example 3 under The notion of function).', 21),('6b8db287-29a4-4384-833a-20fd699016cb'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'true_false', 'The Vertical Line Test states a graph is a function if and only if no vertical line intersects it in more than one point.', 'True', 'The excerpt explicitly gives the Vertical Line Test in those words (note under 1.2.2).', 22),('de587237-9a20-4dd0-83dc-ba36b35317c6'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'true_false', 'If a quadratic function has leading coefficient a<0, its vertex gives a minimum value.', 'False', 'The excerpt states if a<0 the parabola opens downward and the vertex gives a maximum value (summary and ''Minimum and Maximum values'').', 23),('b705894d-8739-467c-8220-c40a73419a6d'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Determine the domain and range of the relation with ordered pairs (−2,1), (−1,0), (0,0), (4,2), (3,5).', 'Domain = {−2, −1, 0, 4, 3}; Range = {1, 0, 2, 5}.', 'Example 1 lists those first components as the domain and the second components 1,0,2,5 as the range (section ''Example 1'' under Domain and range).', 24),('b7c92cb4-3891-47aa-8be4-b1966bdff246'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'For the point P(3,2), state the abscissa and the ordinate.', 'Abscissa = 3; Ordinate = 2.', 'The excerpt defines the first coordinate as the abscissa and the second as the ordinate, illustrated by P(3,2) (section 1.1.2).', 25),('2bf17ffd-6cec-443c-824b-f470bab4625a'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'From Example 2, which of the listed ordered pairs belong to the relation where the second entry is a multiple of the first? The list: (2,4), (4,3), (3,9), (18,−3), (9,3), (7,7), (3,12), (6,18), (30,5).', '(2,4), (3,9), (7,7), (3,12), (6,18).', 'Example 2 states those five ordered pairs belong to the relation ''y is a multiple of x'' (section ''Example 2'').', 26),('d21969d4-9661-4375-8238-b670d3b097a5'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'For the relation R with y = x^2, give the ordered pairs that have first entries 0, 1, −1, −2, 3, −3 as shown in the excerpt.', '(0,0), (1,1), (−1,1), (−2,4), (3,9), (−3,9).', 'Example 3 lists those pairs corresponding to y = x^2 for the given first entries (section ''Example 3'').', 27),('5f6609d8-9616-4e78-8ad7-fa6409f4e029'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Demonstrate in one algebraic step why f(x)=3x+5 is one-to-one as shown in the text.', 'If f(a)=f(b) then 3a+5=3b+5, which implies a=b.', 'The excerpt shows that equating f(a) and f(b) leads to 3a+5=3b+5 and cancellation yields a=b, proving injectivity (section ''Example 1'' under One-to-one function).', 28),('b8852eca-e458-433d-864f-026ad53edfc9'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'State the domain and range of f(x)=3x+5 as given in the examples.', 'Domain = all real numbers; Range = all real numbers.', 'The excerpt explains f(x)=3x+5 is defined for every real x, so both domain and range are the set of all real numbers (section ''Example 2'' under ''For each of the following functions'').', 29),('d12b29cf-95a7-4552-830b-f5b0beb0a2e3'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'For f(x)=√(x−2) given in the text, what are the domain and range?', 'Domain = {x: x ≥ 2}; Range = {y: y ≥ 0}.', 'The excerpt requires the expression under the radical to be non-negative so x−2 ≥ 0 (domain x ≥ 2), and square root values are ≥ 0 (range y ≥ 0) (Example under functions).', 30),('d274cceb-04b5-4630-8776-4b669d307d8c'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Complete the square for f(x)=x^2+6x+11 and state the vertex (as done in the text).', 'f(x)=(x+3)^2+2, so the vertex is (−3,2).', 'The excerpt completes the square: x^2+6x+11=(x+3)^2+2 and identifies the vertex (−3,2) (Example in completing the square section).', 31),('48c156ef-32a9-415f-82aa-5d0ccf2a3962'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Using the example where f(x)=2x+4 and g(x)=3x−1, what is (f+g)(2)?', '13', 'The excerpt computes (f+g)(x)=(2x+4)+(3x−1)=5x+3 and then (f+g)(2)=5(2)+3=13 (example in Sum of functions).', 32),('d522b1f7-cc0f-4661-8078-53494aa31af7'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Given f(x)=x^2+1 and g(x)=x^2+2x−1 from the difference example, what is (f−g)(2)?', '−2', 'The excerpt finds (f−g)(x)=(x^2+1)−(x^2+2x−1)=−2x+2 and evaluates at x=2 to get −4+2=−2 (Difference example solution).', 33),('0dd4fc9c-e8aa-4671-89c7-819474facf26'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Using the linear relation Height = 2.47·(femur length) + 54 from the example, what approximate height does the text compute for a femur of 44 cm?', 'Approximately 163 cm', 'The excerpt computes Height = 2.47(44)+54 = 162.68 and states the woman is approximately 163 cm tall (Application example 1).', 34),('753b86d8-fd8e-483c-8821-430b7fda7072'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Using the same relation Height = 2.47·(femur length) + 54, what approximate height does the excerpt compute for a femur of 51 cm?', 'Approximately 180 cm', 'The excerpt computes Height = 2.47(51)+54 = 179.97 and states the woman is approximately 180 cm tall (Application example 1).', 35),('a0859449-6cfa-46a6-8693-ec6a8a15f843'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'What is the y-intercept of y=(x−3)^2+2 as given in the example?', '11', 'Putting x=0 gives y=(0−3)^2+2=9+2=11, so the y-intercept is 11 (Example under ''Graph of y=a(x−k)^2 + c'').', 36),('0952d011-05fc-4c26-8af0-60e201f57b2e'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Solve x^2−4=0 as shown in the graphical example; give the numerical solutions.', 'x = −2 and x = 2', 'The example graph of x^2−4=0 crosses the x-axis at −2 and 2, so those are the solutions (Graphical method example).', 37),('2ab73102-5c99-46f8-8c7b-07724bd7a405'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Solve −x^2+6x−9=0 as in the worked example; give the value of x.', 'x = 3', 'The excerpt rewrites −x^2+6x−9=−(x−3)^2, so the graph touches the x-axis at x=3 and the solution is x=3 (Example 3 under ''Graphical method'').', 38),('30306db0-230b-485b-8baa-188ef47a500b'::uuid, '6c8eb114-90f2-4db5-87ac-e3d36bbca276'::uuid, 'fill_blank', 'Give the solution interval for x^2−6x+8<0 found graphically in the text.', '(2,4)', 'The worked example identifies the parabola is below the x-axis between roots x=2 and x=4, so the solution interval is (2,4) (section ''Graphical method of solving quadratic inequalities'').', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('bf60e95d-88ce-4dac-88e4-b05a9743f27a'::uuid, '5af3c626-2c4c-4ef3-889a-08231c848601'::uuid, 'A set of ordered pairs.', TRUE, 0),('bd98ddbb-7705-454f-80b8-9560234d6418'::uuid, '5af3c626-2c4c-4ef3-889a-08231c848601'::uuid, 'A single number.', FALSE, 1),('cbb43b29-a2d4-4c50-81e1-229f5546f7f2'::uuid, '5af3c626-2c4c-4ef3-889a-08231c848601'::uuid, 'A graph region only.', FALSE, 2),('b36ebe09-e789-40a7-8cb0-8060d2a91094'::uuid, '5af3c626-2c4c-4ef3-889a-08231c848601'::uuid, 'A list of unrelated numbers.', FALSE, 3),('2926c543-4e27-413b-857e-5079ff275a4a'::uuid, '34fea43f-0f9e-41ef-8cd1-66c1945a6087'::uuid, '3 is the abscissa and 2 is the ordinate.', TRUE, 0),('91279677-8e9e-45bb-83d8-123bee75bad3'::uuid, '34fea43f-0f9e-41ef-8cd1-66c1945a6087'::uuid, '3 is the ordinate and 2 is the abscissa.', FALSE, 1),('ce7c2fe0-3e71-47b6-8ba6-f06c6e38db65'::uuid, '34fea43f-0f9e-41ef-8cd1-66c1945a6087'::uuid, '3 is the origin and 2 is the ordinate.', FALSE, 2),('6bedd4b1-3898-4c57-8eb1-590d9542eb5a'::uuid, '34fea43f-0f9e-41ef-8cd1-66c1945a6087'::uuid, '3 is the x-intercept and 2 is the y-intercept.', FALSE, 3),('14205466-8cc6-4ada-85d6-592bb963332b'::uuid, 'bb199ac5-9d90-4867-81c5-d198c558cbac'::uuid, '(0, 0)', TRUE, 0),('791d465f-c259-4e8c-8a46-98620213b2fc'::uuid, 'bb199ac5-9d90-4867-81c5-d198c558cbac'::uuid, '(1, 0)', FALSE, 1),('2c0bd218-59c8-45ce-8fb3-428118596514'::uuid, 'bb199ac5-9d90-4867-81c5-d198c558cbac'::uuid, '(0, 1)', FALSE, 2),('237f6f72-0d9d-47e4-8a20-614a80bf3508'::uuid, 'bb199ac5-9d90-4867-81c5-d198c558cbac'::uuid, '(1, 1)', FALSE, 3),('67afca4d-495c-421e-8e11-fcc3bf7f4502'::uuid, 'f43ab72f-f701-4eab-8f5b-08f59ced5546'::uuid, 'The x-axis', TRUE, 0),('2f912567-f668-434c-8cf6-11f76ae5b012'::uuid, 'f43ab72f-f701-4eab-8f5b-08f59ced5546'::uuid, 'The y-axis', FALSE, 1),('3dd08e3f-a25d-4eb1-830d-5836f9d91972'::uuid, 'f43ab72f-f701-4eab-8f5b-08f59ced5546'::uuid, 'The origin axis', FALSE, 2),('12c6cc1e-0b51-4670-8d9c-e2a560c757cf'::uuid, 'f43ab72f-f701-4eab-8f5b-08f59ced5546'::uuid, 'The axis of symmetry', FALSE, 3),('2cfd1939-a237-47a6-88d2-840c2fdd1f73'::uuid, 'be7e806e-90ca-478c-87d8-c54f584c2b29'::uuid, 'Arithmetic pattern', TRUE, 0),('22678487-57c2-421e-8f48-99b1bf316a7f'::uuid, 'be7e806e-90ca-478c-87d8-c54f584c2b29'::uuid, 'Geometric pattern', FALSE, 1),('dc6f6041-357b-4880-8742-9ab58c49b9db'::uuid, 'be7e806e-90ca-478c-87d8-c54f584c2b29'::uuid, 'Even numbers pattern only', FALSE, 2),('646c750b-babd-4496-8640-27f9530aa33c'::uuid, 'be7e806e-90ca-478c-87d8-c54f584c2b29'::uuid, 'Repeating pattern', FALSE, 3),('2b740e4f-5c33-4cd8-8331-ca342ea646b3'::uuid, 'e146ed63-a39b-4fed-82e0-002da29430f3'::uuid, '11', TRUE, 0),('c43bbc49-315b-4f89-85e6-a47084d305f5'::uuid, 'e146ed63-a39b-4fed-82e0-002da29430f3'::uuid, '10', FALSE, 1),('e68c510e-af63-4cc7-8329-1a83385f03a5'::uuid, 'e146ed63-a39b-4fed-82e0-002da29430f3'::uuid, '12', FALSE, 2),('a5806ff3-2bff-4f01-8009-33465243e96c'::uuid, 'e146ed63-a39b-4fed-82e0-002da29430f3'::uuid, '9', FALSE, 3),('39e1de50-0416-4fd4-8dd2-982b3bed6ad3'::uuid, 'ede2c5cb-9453-4ea1-8e13-b236722c8392'::uuid, '{−2, −1, 0, 3, 4}', TRUE, 0),('70af49fb-9465-40b9-8538-cb54ee2f8ff7'::uuid, 'ede2c5cb-9453-4ea1-8e13-b236722c8392'::uuid, '{1, 0, 0, 2, 5}', FALSE, 1),('a2b176ed-559e-4607-852e-ce62e59c9855'::uuid, 'ede2c5cb-9453-4ea1-8e13-b236722c8392'::uuid, '{−2, −1, 0, 2, 3}', FALSE, 2),('285a8521-0e8a-47b0-80fb-94987ca705f8'::uuid, 'ede2c5cb-9453-4ea1-8e13-b236722c8392'::uuid, '{1,2,3,4,5}', FALSE, 3),('0b96ac13-b8d2-468b-8f1a-18003a0401aa'::uuid, '35abf2a7-d42e-4246-8735-f828bc64c92c'::uuid, 'No two distinct ordered pairs have the same first element.', TRUE, 0),('93b3bc07-5a3d-4677-8887-c122300f4278'::uuid, '35abf2a7-d42e-4246-8735-f828bc64c92c'::uuid, 'Every relation is a function.', FALSE, 1),('69d39ea2-0293-4b35-8994-cbc32c441e62'::uuid, '35abf2a7-d42e-4246-8735-f828bc64c92c'::uuid, 'A function always maps multiple outputs to one input.', FALSE, 2),('b15da492-2090-4573-8443-24092aa78c39'::uuid, '35abf2a7-d42e-4246-8735-f828bc64c92c'::uuid, 'A function is any graph on the plane.', FALSE, 3),('079a5353-377f-4372-8df4-c53d8ceee64b'::uuid, '0151ded4-e6ac-4c64-8194-d5988679df02'::uuid, '(2,4), (3,9), (7,7), (3,12), (6,18)', TRUE, 0),('e02cc6fd-2d5f-476c-868f-1dc951004ca2'::uuid, '0151ded4-e6ac-4c64-8194-d5988679df02'::uuid, '(4,3), (18,−3), (30,5)', FALSE, 1),('caba6672-72be-4b12-8675-a787d98a1dcd'::uuid, '0151ded4-e6ac-4c64-8194-d5988679df02'::uuid, '(9,3), (30,5), (4,3)', FALSE, 2),('79e0ad8a-c5d8-40e5-84b5-86203366ee3c'::uuid, '0151ded4-e6ac-4c64-8194-d5988679df02'::uuid, '(2,4), (4,3), (9,3), (6,18)', FALSE, 3),('82126837-280d-4480-8f0a-6ea13aaded1e'::uuid, 'ed2770e6-71de-4c94-81be-67b8d9d842e4'::uuid, 'A numerical relation is a function iff no vertical line intersects its graph in more than one point.', TRUE, 0),('da8b752b-3bfc-40ad-8f19-ac062c5978d1'::uuid, 'ed2770e6-71de-4c94-81be-67b8d9d842e4'::uuid, 'A graph is a function iff it is symmetric about the y-axis.', FALSE, 1),('5b04d11b-fe7f-468b-8e50-eeb30463bb9c'::uuid, 'ed2770e6-71de-4c94-81be-67b8d9d842e4'::uuid, 'A relation is a function iff it has equal domain and range.', FALSE, 2),('b6882a45-db54-40ab-804f-54079895ec7b'::uuid, 'ed2770e6-71de-4c94-81be-67b8d9d842e4'::uuid, 'A graph is a function iff every horizontal line intersects it at most once.', FALSE, 3),('177effc6-2620-453e-88fc-f65fcbec066a'::uuid, 'f40c70a6-8669-42a0-8cd3-1eafb3b62f7f'::uuid, 'Because f(a)=f(b) leads to 3a+5=3b+5 and so a=b.', TRUE, 0),('578d5c41-18d8-4209-81af-a9e1ad517226'::uuid, 'f40c70a6-8669-42a0-8cd3-1eafb3b62f7f'::uuid, 'Because its graph is a parabola.', FALSE, 1),('ea90e7c0-ea7c-4a15-8110-279cd32b0235'::uuid, 'f40c70a6-8669-42a0-8cd3-1eafb3b62f7f'::uuid, 'Because its range is non-negative only.', FALSE, 2),('ae968d27-b298-4c53-819b-5cd1ae0bd0f0'::uuid, 'f40c70a6-8669-42a0-8cd3-1eafb3b62f7f'::uuid, 'Because it is constant.', FALSE, 3),('4785d19e-d475-4bd3-8c