INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'Mathematics', 'Unit 2', 'Molarum Grade 10 — Mathematics Unit 2: Polynomial Functions', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 2: Polynomial Functions.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('8462d143-5d22-41c3-8d7e-00e9ac32b572'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'Which of the following best matches the definition of a polynomial function given in the text?', 'A function p(x)=a_n x^n + a_{n-1} x^{n-1} + ... + a_1 x + a_0 where n is a non-negative integer and a_n ≠ 0', 'Definition 2.1 in the excerpt defines a polynomial function as p(x)=a_n x^n + ... + a_0 with n a non-negative integer and a_n ≠ 0.', 0),('d1384bfd-0109-4871-8640-02f8ad855107'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'What is the domain of a polynomial function as stated in the text?', 'The set of all real numbers', 'The text states that the domain of a polynomial function is the set of all real numbers.', 1),('f7645da4-b2c1-410e-897c-9581fee41e83'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'What is the degree of the polynomial f(x)=3x^3 − 9x^2 + 5x + 2 as given in Example 1?', '3', 'Example 1 identifies f(x)=3x^3 − 9x^2 + 5x + 2 as degree 3 because the highest exponent is 3.', 2),('98ccfefa-2bf2-4221-874d-c82222c3f18d'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'What is the leading coefficient of f(x)=3x^3 − 9x^2 + 5x + 2?', '3', 'In Example 1 the leading coefficient is the coefficient of the highest power x^3, which is 3.', 3),('78134f89-b6d6-4b74-8583-b26bec81c802'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'What is the constant term of h(x)=−5x^4 + 8x^3 + 2x^2 − 3x + 7 from Example 1?', '7', 'Example 1 states the constant term is the constant term a_0, here 7.', 4),('42856506-77fa-41f5-808e-b7d40dadeeaa'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'Which of the following is NOT a polynomial function according to the examples in the text?', 'g(x)=4x^{−2} + 3x^{−1} − 7', 'Example 2 explains that terms with negative exponents (like x^{−2}, x^{−1}) mean the expression is not a polynomial.', 5),('02912fb6-8877-4e67-8ffa-d096b468e399'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'The sum of f(x)=2x^4 + 5x^3 + x^2 + 9x + 4 and g(x)=−3x^3 + 5x^2 − 5x − 9 from Example 1 is:', '2x^4 + 2x^3 + 6x^2 + 4x − 5', 'The solution groups like terms to give 2x^4 + (5−3)x^3 + (1+5)x^2 + (9−5)x + (4−9) = 2x^4 + 2x^3 + 6x^2 + 4x − 5.', 6),('4a85676b-9a6a-4555-82dd-2394c489a0b6'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'Compute (2x + 3)(3x^2 − 5x + 6) as in Example 3; which expression is correct?', '6x^3 − x^2 − 3x + 18', 'Example 3 multiplies each term and combines like terms to obtain 6x^3 − x^2 − 3x + 18.', 7),('920bbd35-2d6d-4f16-8abd-1bd461ce0096'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'What does the text state about the degree of the product of two non-zero polynomials f and g of degrees m and n?', 'The degree of f·g is m + n', 'Observation in Example 3 states the degree of f·g is m + n when degrees of f and g are m and n respectively.', 8),('7b438edf-c433-433e-8aee-2e441cea1fe9'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'According to the Remainder Theorem in the text, what is the remainder when f(x) is divided by (x − c)?', 'f(c)', 'Theorem 2.2 states that the remainder on division by (x − c) is f(c).', 9),('39485bb4-4d9a-4c34-830a-eaa02c05b368'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'Which statement is the Factor Theorem as given in the text?', 'If f(c)=0 then x−c is a factor of f(x)', 'Theorem 2.3 states that if f(c)=0 then x−c is a factor of f(x), and conversely.', 10),('281c7525-279c-4c17-8dbe-a9abee014798'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'In Example 6 the quotient when x^5 + 5x^3 − 2x^2 + 7 is divided by x^2 + 2x + 1 is:', 'x^3 − 2x^2 + 8x − 16', 'Example 6 shows the quotient of that division is x^3 − 2x^2 + 8x − 16 with remainder 24x + 23.', 11),('f1f28758-daf2-4ded-8bc1-7ad896d44db5'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'Which description matches the Rational Zero Test as stated in the unit?', 'If q=p/q (in lowest terms) is a rational zero then p divides a_0 and q divides a_n', 'Theorem 2.5 states that for integer-coefficient polynomials, if q=p/q in lowest terms is a zero then p divides the constant term a_0 and q divides the leading coefficient a_n.', 12),('03f2dd6a-9a56-4914-82a1-2f1ea9ce5f5e'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'What does the Location Theorem guarantee if f(a) and f(b) have opposite signs?', 'There is at least one zero of f between a and b', 'Theorem 2.4 states that if f(a) and f(b) have opposite signs then there is at least one zero between a and b.', 13),('aa691692-9f88-4211-8b54-401882711598'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'From the worked example for f(x)=x^2 + 2x − 3, what is the turning point (vertex)?', '(−1, −4)', 'Completing the square gives f(x)=−4 + (x+1)^2, so the minimum occurs at x=−1 with value −4, i.e. (−1,−4).', 14),('daa20c0a-6b61-4edb-8673-c7c24c83e0db'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'For f(x)=−x^2 − 6x − 8, what is the turning point shown in the example?', '(−3, 1)', 'Completing the square yields f(x)=1 − (x+3)^2, so the maximum occurs at (−3,1) as shown in the example.', 15),('0265054b-9017-450c-80e3-d3a2f44b8e1c'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'In the wire problem (Example 1 in Applications), what is the maximum area that a rectangle made from a 56 m wire can enclose?', '196 m^2', 'The solution rewrites area A=−x^2 + 28x = 196 − (x−14)^2, so the maximum value is 196 m^2 attained when x=14.', 16),('2f67de9c-e4f1-4c74-89ac-8adc148d8a02'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'According to the same wire example, what are the dimensions of the rectangle that give the maximum area?', '14 m by 14 m', 'Setting x=14 from the maximization gives y=28−x=14, so the rectangle is 14 m by 14 m (a square).', 17),('621ffed8-b014-4fc2-8470-9132aad4dd8a'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'Given g(x)=x^3 + 4x^2 − 3x − 18 = (x + 3)^2 (x − 2) in the text, which zero has multiplicity 2?', '−3', 'The factor (x+3) is squared, so the zero x=−3 is of multiplicity 2 as shown in the example.', 18),('1868e9b8-1623-4998-892c-dbf306c1352f'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'multiple_choice', 'How does the graph of an even-degree polynomial with positive leading coefficient behave for large |x| according to the observations?', 'Both ends of the graph go upward (large positive)', 'The observations note that when degree is even and leading coefficient positive, values become large positive and the graph goes upward both far to the right and left.', 19),('04fcebde-f218-4d85-8125-421fd1785a4c'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'true_false', 'The constant function f(x)=b with b≠0 is a polynomial function of degree zero.', 'True', 'The note states the constant function f(x)=b (b≠0) is a polynomial function with degree zero.', 20),('a29fe09e-121c-4407-8732-ed33f233e33b'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'true_false', 'If the remainder r(x) is zero when f(x) is divided by d(x), then d(x) divides f(x) exactly.', 'True', 'The Polynomial Division Theorem notes that when the remainder r(x)=0, d(x) divides f(x) exactly (division is exact).', 21),('853d7b6a-f280-41dc-8ef2-ce3009711f62'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'true_false', 'The sum of two polynomial functions is not necessarily a polynomial function.', 'False', 'The text explicitly states the sum of two polynomial functions is a polynomial function.', 22),('3ad7c259-28da-4869-8c89-e81c5036b826'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'true_false', 'A polynomial function''s graph is a smooth curve with no sharp corners.', 'True', 'The notes state that the graph of a polynomial is a smooth curve (has no sharp corner), distinguishing it from functions like |x|.', 23),('3e2a072e-03e9-496b-841f-c77d27fc1807'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Define the term ''leading coefficient'' for a polynomial function as given in the unit.', 'The leading coefficient is the coefficient a_n of the term a_n x^n corresponding to the highest power of x in the polynomial.', 'In the definition section the text states a_n is called the leading coefficient and a_n x^n the leading term.', 24),('e94d95a9-69e1-40fb-8b36-55b3c26f1ccb'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Give the domain of any polynomial function according to the text.', 'The domain of any polynomial function is the set of all real numbers.', 'The excerpt states repeatedly that the domain of a polynomial function is all real numbers.', 25),('d1cfdb10-129a-4d17-831a-828b13db692b'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'List the four fundamental operations on polynomial functions mentioned in the unit contents.', 'Addition, subtraction, multiplication and division.', 'Section 2.2 and the Unit Contents list the four fundamental operations as addition, subtraction, multiplication and division of polynomials.', 26),('b84e5b56-8c1e-43bc-87a5-3e6401b7e322'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Give a one-sentence statement of the Polynomial Division Theorem as in the text.', 'If f(x) and d(x) are polynomials with d(x)≠0 and deg d ≤ deg f, then there exist unique polynomials q(x) and r(x) such that f(x)=d(x)q(x)+r(x) with r(x)=0 or deg r < deg d.', 'Theorem 2.1 states existence and uniqueness of q(x) and r(x) with the remainder of degree less than the divisor or zero.', 27),('8d9c4710-94bf-4c85-8ca5-cb6a34b336d4'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'State the Remainder Theorem in one sentence.', 'If f(x) is divided by (x − c) then the remainder is f(c).', 'Theorem 2.2 shows that evaluating f at c gives the remainder upon division by x−c because (c−c)q(c)=0 leaves the constant remainder.', 28),('b44d4b93-b03d-4dce-8e88-899cf71b4a0b'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'What does it mean for a zero c to have multiplicity k in the polynomial f(x)?', 'It means (x−c)^k is a factor of f(x) but (x−c)^{k+1} is not, so c is a zero of multiplicity k.', 'Definition 2.8 defines multiplicity as the exponent k such that (x−c)^k divides f(x) but (x−c)^{k+1} does not.', 29),('93677b24-36f2-4dcd-8c45-084c5a451ba7'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Using the Factor Theorem from the unit, explain how to test whether x−c is a factor of f(x).', 'Evaluate f(c); if f(c)=0 then x−c is a factor, otherwise it is not.', 'Theorem 2.3 states f(c)=0 implies x−c is a factor, so computing f(c) is the test.', 30),('0f7df8ae-5ce7-4a57-8561-7005ab9059cf'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Summarize the Rational Zero Test procedure in one sentence.', 'List factors p of the constant term a_0 and factors q of the leading coefficient a_n, form ±p/q in lowest terms and test which values give f(q)=0 to find rational zeros.', 'Theorem 2.5 and the listed steps instruct to take factors of a_0 and a_n, form p/q candidates and check which satisfy f=0.', 31),('66b4d522-b658-4361-8bd1-878c526e7ae5'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'What is the degree of f(x)=−2x + 5 as given in Example 1?', '1', 'Example 1 states f(x)=−2x + 5 is a polynomial of degree 1 since the highest power of x is 1.', 32),('34da7bb9-3fd2-4650-8199-5d6f5d38431a'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'What is the leading coefficient of f(x)=3x^2 + x − 3 from Example 1?', '3', 'Example 1 identifies the leading coefficient of 3x^2 + x − 3 as 3, the coefficient of x^2.', 33),('f702f1c4-3588-4b01-8037-0020fd079b9b'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'What is the constant term of the product (2x + 3)(3x^2 − 5x + 6) as calculated in Example 3?', '18', 'Example 3 gives the product 6x^3 − x^2 − 3x + 18, so the constant term is 18.', 34),('06ee6830-7762-427a-8963-108b2a120382'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'When 4x^3 + 4x^2 − x + 4 is divided by 2x − 1 (Example 5), what is the remainder?', '5', 'The worked division in Example 5 yields quotient 2x^2 + 3x + 1 and remainder 5.', 35),('048b45e1-0b43-40ff-82f8-69ff2e2bc2b9'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'What is the remainder when x^5 + 5x^3 − 2x^2 + 7 is divided by x^2 + 2x + 1 as in Example 6?', '24x + 23', 'Example 6 shows the division gives remainder 24x + 23 after computing quotient and remainder.', 36),('eaf69eb7-c487-480a-816c-ab37d1c4722f'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Compute the maximum area obtainable from a wire of length 56 m bent into a rectangle, as shown in the Applications example.', '196', 'The example rewrites A=−x^2 + 28x = 196 − (x−14)^2, so the maximum area is 196 (m^2).', 37),('4fc06fcd-030d-4ba7-8020-02046fa2d437'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'Find the two real numbers whose difference is 16 and whose product is minimum, as solved in Example 2.', '8 and −8', 'Setting y=x−16 and A=x(x−16) leads to A=(x−8)^2 − 64, so minimum occurs at x=8 giving y=−8, hence 8 and −8.', 38),('3039eea2-ce01-4239-8b8e-0b51ce57bd8f'::uuid, 'c7e1fca1-fd8c-4dea-8ee7-ebcbd6c91192'::uuid, 'fill_blank', 'When 3x^3 − 4x^2 + b − 5 is divided by x − 2 the remainder is 10; what is b as found in the example?', '7', 'By the Remainder Theorem f(2)=3(2)^3 −4(2)^2 + b −5 = b + 3 = 10, so b=7 as shown in the example.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('f3b6566b-3dc3-45ae-8e68-21e6abb11c89'::uuid, '8462d143-5d22-41c3-8d7e-00e9ac32b572'::uuid, 'A function p(x)=a_n x^n + a_{n-1} x^{n-1} + ... + a_1 x + a_0 where n is a non-negative integer and a_n ≠ 0', TRUE, 0),('08db2025-4a78-4645-8776-535e234cb821'::uuid, '8462d143-5d22-41c3-8d7e-00e9ac32b572'::uuid, 'A function that can contain negative integer powers of x', FALSE, 1),('6ed059f9-67d3-4a78-8bb0-d0c1d472e6b8'::uuid, '8462d143-5d22-41c3-8d7e-00e9ac32b572'::uuid, 'Any function involving radicals of x', FALSE, 2),('48321bf7-1993-4e39-8370-b8549a07ea87'::uuid, '8462d143-5d22-41c3-8d7e-00e9ac32b572'::uuid, 'A function whose domain is only integers', FALSE, 3),('d467af33-8b54-4ff5-89a6-03545bbad537'::uuid, 'd1384bfd-0109-4871-8640-02f8ad855107'::uuid, 'The set of all real numbers', TRUE, 0),('59837429-7e7e-4605-8edc-10c8bc8ea300'::uuid, 'd1384bfd-0109-4871-8640-02f8ad855107'::uuid, 'Only positive real numbers', FALSE, 1),('d4678672-1e95-409f-8e9b-b0c3b7e22fca'::uuid, 'd1384bfd-0109-4871-8640-02f8ad855107'::uuid, 'Only integers', FALSE, 2),('2763a73a-0310-4612-85d0-752ce9b6f392'::uuid, 'd1384bfd-0109-4871-8640-02f8ad855107'::uuid, 'Only rational numbers', FALSE, 3),('8a812a59-28f4-468b-8a24-fa3c97f0ede1'::uuid, 'f7645da4-b2c1-410e-897c-9581fee41e83'::uuid, '3', TRUE, 0),('f0b3711b-ddf4-40a3-88c3-bd7050db6ac1'::uuid, 'f7645da4-b2c1-410e-897c-9581fee41e83'::uuid, '2', FALSE, 1),('121c9e45-5676-4122-88ab-f97062eeb187'::uuid, 'f7645da4-b2c1-410e-897c-9581fee41e83'::uuid, '1', FALSE, 2),('90a1e985-1da1-47c5-8814-6ac031bdec09'::uuid, 'f7645da4-b2c1-410e-897c-9581fee41e83'::uuid, '0', FALSE, 3),('57256eff-2a72-4810-8ff8-8442fb4847a0'::uuid, '98ccfefa-2bf2-4221-874d-c82222c3f18d'::uuid, '3', TRUE, 0),('d7233649-5ff7-44f9-85df-450b4570bc94'::uuid, '98ccfefa-2bf2-4221-874d-c82222c3f18d'::uuid, '−9', FALSE, 1),('76a3a142-32af-476d-83e9-5970b5a8987b'::uuid, '98ccfefa-2bf2-4221-874d-c82222c3f18d'::uuid, '5', FALSE, 2),('35f92fcd-d50b-437c-8a93-a9457e80cafa'::uuid, '98ccfefa-2bf2-4221-874d-c82222c3f18d'::uuid, '2', FALSE, 3),('b7f485d7-79b3-4e58-8ecf-eae8756638a6'::uuid, '78134f89-b6d6-4b74-8583-b26bec81c802'::uuid, '7', TRUE, 0),('770b190e-40f9-430b-8389-836e04b19e55'::uuid, '78134f89-b6d6-4b74-8583-b26bec81c802'::uuid, '−5', FALSE, 1),('a60185be-ee3b-4ca1-8af9-ef01c33c9632'::uuid, '78134f89-b6d6-4b74-8583-b26bec81c802'::uuid, '8', FALSE, 2),('752546c9-5bfa-4242-8b00-f68f2de6376b'::uuid, '78134f89-b6d6-4b74-8583-b26bec81c802'::uuid, '2', FALSE, 3),('c6143e81-7bfd-4f12-8057-d0deb1088d09'::uuid, '42856506-77fa-41f5-808e-b7d40dadeeaa'::uuid, 'g(x)=4x^{−2} + 3x^{−1} − 7', TRUE, 0),('03bbe63f-211e-4538-8d97-f7e35a479ada'::uuid, '42856506-77fa-41f5-808e-b7d40dadeeaa'::uuid, 'f(x)=2x^2 + 3x − 5', FALSE, 1),('f53ac25b-08c2-4051-8f85-c6c79199ed51'::uuid, '42856506-77fa-41f5-808e-b7d40dadeeaa'::uuid, 'k(x)=5', FALSE, 2),('10e4aa9f-1e75-4cdf-8e80-ce35851bcabd'::uuid, '42856506-77fa-41f5-808e-b7d40dadeeaa'::uuid, 'h(x)=x^4 + 2x − 5', FALSE, 3),('a2ff21b5-6edc-4723-887e-3ed445ffe8b9'::uuid, '02912fb6-8877-4e67-8ffa-d096b468e399'::uuid, '2x^4 + 2x^3 + 6x^2 + 4x − 5', TRUE, 0),('6a311a53-9718-4f1d-81f8-907ba8a2a95e'::uuid, '02912fb6-8877-4e67-8ffa-d096b468e399'::uuid, '−x^4 + 0x^3 + 6x^2 + 4x − 5', FALSE, 1),('d54ddc86-39c8-48ce-8231-e2fa151279ea'::uuid, '02912fb6-8877-4e67-8ffa-d096b468e399'::uuid, '2x^4 + 8x^3 + 6x^2 + 4x − 5', FALSE, 2),('a4ff7ed9-0eb5-4c27-8016-d005eaf3c157'::uuid, '02912fb6-8877-4e67-8ffa-d096b468e399'::uuid, '2x^4 + 2x^3 + 4x^2 + 9x − 5', FALSE, 3),('13a01f3e-9cf1-44b0-84d7-36feca891c9f'::uuid, '4a85676b-9a6a-4555-82dd-2394c489a0b6'::uuid, '6x^3 − x^2 − 3x + 18', TRUE, 0),('8f1f5987-48a4-4882-88f2-698321cb70bf'::uuid, '4a85676b-9a6a-4555-82dd-2394c489a0b6'::uuid, '6x^3 − 10x^2 + 12x + 9x^2 − 15x + 18', FALSE, 1),('59b31612-6968-4050-89ed-0bce68461cb2'::uuid, '4a85676b-9a6a-4555-82dd-2394c489a0b6'::uuid, '6x^3 − 15x + 18', FALSE, 2),('af894e65-a5ce