INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'Mathematics', 'Unit 4', 'Molarum Grade 10 — Mathematics Unit 4: Trigonometric Functions', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 4: Trigonometric Functions.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('db34a448-fb07-4bee-85a4-caa8ffd75c99'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'Convert 180° into radians.', 'π', 'Using the relation π rad = 180°, 180° equals π radians, as stated in the degree–radian relation in the excerpt.', 0),('efc3fe10-ee2a-4818-8154-47b6b9277dfe'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'Convert π/3 radian to degrees.', '60°', 'Degree measure = (180/π) × radian measure, so (180/π)×(π/3)=60°, as given by the conversion relations in the excerpt.', 1),('1112baf9-50ac-4c30-8bfb-78307e390a84'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is the radian measure of 90°?', 'π/2', 'Since π rad = 180°, multiply 90° by π/180 to get π/2 radians, using the degree–radian relation from the excerpt.', 2),('6029acb2-9fd4-4238-811b-9b6b76d49cba'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'A point P(5,12) lies on the terminal side of angle θ in standard position. What is sin θ?', '12/13', 'For point (x,y) on terminal side, r=√(x^2+y^2)=13 and sinθ=y/r=12/13, as shown in the worked example with P(5,12).', 3),('ce349090-8fa2-456d-8ff2-d02b2550745c'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'Which identity is always true for any angle x on the unit circle?', 'cos^2 x + sin^2 x = 1', 'On the unit circle a^2 + b^2 =1 for coordinates (a,b)=(cos x,sin x), which gives cos^2 x + sin^2 x = 1 as proved in the excerpt.', 4),('66e96ad6-2330-4f50-804f-74b649e0bb4b'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is sin 30°?', '1/2', 'The table of common angles lists sin30° = 1/2, as given in the excerpt''s table of values.', 5),('ded39e96-f0eb-403c-832e-a463c0c499cd'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'If sin x > 0 and cos x < 0, in which quadrant is x located?', 'II', 'The excerpt''s quadrant sign table shows sine positive and cosine negative in the second quadrant, so x lies in quadrant II.', 6),('567eadbe-f2e9-4ccf-8769-2db0eff203ea'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is the period of the sine function y = sin x (in radians)?', '2π', 'The text states that the sine function repeats every 2π radians, so its period is 2π, as shown in the graph discussion.', 7),('45e0fe44-774c-4e59-81dc-7ebc369f0727'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is tan 45°?', '1', 'From the table of common angles tan45° = 1, as recorded in the excerpt''s values for standard angles.', 8),('11346835-e3a2-4971-80b5-b8c1b9bf4251'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is cos π (cosine of π radians)?', '−1', 'The unit circle values listed in the excerpt give cosπ = −1 for the quadrantal angle π radians (180°).', 9),('120fe266-de38-4aee-8ecc-e50e7f195a14'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is the reference angle of 245°?', '65°', 'For a third quadrant angle (180°–270°) the reference angle is θ − 180°, so 245° − 180° = 65°, as shown in the reference angle examples.', 10),('570c7eb3-4569-4431-8c2b-8d90c06b434d'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is the complementary angle of 57°?', '33°', 'Complementary angles sum to 90°, so 90° − 57° = 33°, as demonstrated in the complementary angle example.', 11),('1f70ab22-051e-4070-85d9-47fb292ce02b'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'Which of the following is a co-terminal angle of 30° obtained by adding 360°?', '390°', 'Adding 360° to 30° gives 390°, and the excerpt explains co-terminal angles differ by multiples of 360°.', 12),('606d457a-f499-459d-8ab2-ffb663c536b2'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'Evaluate sec 30° (secant of 30°) using cosine reciprocal.', '2/√3', 'secθ is 1/cosθ and cos30° = √3/2, so sec30° = 1/(√3/2) = 2/√3, as shown in the secant example.', 13),('bd11dcd1-f83b-443b-89ab-694176feb717'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'If sin x = −5/13 and x is in the third quadrant, what is cos x?', '−12/13', 'Use sin^2x+cos^2x=1: cos^2x=1−(25/169)=144/169 so cos x = −12/13 since cosine is negative in the third quadrant, following the identity and quadrant sign rules in the text.', 14),('8d3619a2-6cf8-4d1e-8aef-422450ac2622'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is the period of the tangent function y = tan x (in radians)?', 'π', 'The excerpt explains that the tangent function repeats every π radians, so its period is π, as shown in the tangent graph discussion.', 15),('05699a3c-46ab-4ddf-8ebf-e8251e9a652a'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'For which x (in radians) is sin x = 0 according to the excerpt?', 'x = nπ, where n is any integer', 'The text states sin x = 0 when x is an integral multiple of π, i.e., x = nπ for integer n, which is the given form in the excerpt.', 16),('eeb7dd80-35ba-4d01-8bdf-28a7eab166c5'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'Which formula gives cos(α + β)?', 'cosα cosβ − sinα sinβ', 'The addition and subtraction identities in the excerpt list cos(α+β)=cosα cosβ − sinα sinβ, so that is the correct formula.', 17),('8682bacb-34b9-4641-868f-9df032387803'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'What is sin 75° expressed exactly using sum formula values?', '(√6 + √2)/4', 'Using sin(75°)=sin(30°+45°)=sin30 cos45+cos30 sin45 yields (1/2)(√2/2)+(√3/2)(1/√2)=(√6+√2)/4, as derived in the excerpt''s example.', 18),('8acbc462-bf9e-4805-8645-6b7e70139b68'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'multiple_choice', 'In which pair of quadrants is tan x positive according to the sign table?', 'I and III', 'The quadrant sign table in the excerpt shows tan x is positive in quadrants I and III, so those are the correct quadrants.', 19),('045d6ebc-158a-41e4-8bd5-7e1623818f4f'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'true_false', 'One complete revolution is 2π radians.', 'True', 'The excerpt states one complete revolution subtends an angle of 2π radian at the center, so the statement is true.', 20),('5b79dea7-117e-460a-851e-73eb04c39ad4'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'true_false', 'sin(−x) = sin x for all x.', 'False', 'The excerpt explains sin(−x)=−sin x (odd function), so sin(−x)=sin x is false except at specific points.', 21),('3da763bd-65e7-490c-8c12-b76e19a43c5c'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'true_false', 'cos(2π + x) = cos x for any x.', 'True', 'The excerpt states cos(2nπ + x) = cos x for any integer n, so cos(2π + x) = cos x is true by periodicity.', 22),('6f27f797-640b-49c6-89ac-e18f9010bb5c'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'true_false', 'The range of the sine function is the set of all real numbers.', 'False', 'The excerpt states the range of sine is −1 ≤ y ≤ 1, not all real numbers, so the statement is false.', 23),('0dce964a-0879-4a19-8f26-6910efb3e8ff'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'State the formula to convert degree measure to radian measure.', 'Radian measure = (π/180) × degree measure', 'The excerpt gives radian measure = (π/180) times the degree measure as the conversion relation between degrees and radians.', 24),('0e9d6995-2a63-45d5-8026-3938645163a6'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'What two conditions define an angle in standard position?', 'Its vertex is at the origin and its initial side lies on the positive x-axis', 'The excerpt defines an angle in standard position by those two conditions: vertex at origin and initial side on the positive x-axis.', 25),('4505372c-4588-4d62-8b11-7851595a2542'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Give the coordinates of the quadrantal points A, B, C and D on the unit circle as listed in the excerpt.', 'A(1, 0), B(0, 1), C(−1, 0), D(0, −1)', 'The excerpt lists quadrantal points A, B, C, D with coordinates (1,0), (0,1), (−1,0), (0,−1) on the unit circle.', 26),('66d2645b-520a-40b1-8b91-b2ffd4e4c438'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'State the formula relating arc length l, radius r and central angle θ (in radians).', 'l = rθ', 'The excerpt gives l = rθ for arc length in a circle of radius r subtended by central angle θ in radians.', 27),('8cf7cdee-7981-4f68-8962-62667585d878'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'State the Pythagorean trigonometric identity used on the unit circle.', 'cos^2 x + sin^2 x = 1', 'The excerpt derives cos^2 x + sin^2 x = 1 from the Pythagoras theorem applied to a right triangle inscribed in the unit circle.', 28),('db3f095b-1917-4042-88a3-6aeeb5713c83'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Express sin(π/2 − α) in terms of cos α.', 'sin(π/2 − α) = cos α', 'The excerpt lists complementary-angle identities and states sin(π/2 − α) = cos α for acute α.', 29),('d260152b-ae61-4d0c-8ab1-1012b87913b8'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Express cos 155° in terms of its reference angle.', '−cos25°', '155° is in quadrant II with reference angle 25°, and cosine is negative there, so cos155° = −cos25°, as shown in the example.', 30),('bc0f1b66-1c9c-4247-898b-755be59fef84'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'If sin 3A = cos (A − 26°) and 3A is an acute angle, find A.', '29°', 'Using sin3A = cos(90°−3A) and equating to cos(A−26°) leads to 90°−3A = A−26°, giving 4A = 116° and A = 29°, as in the worked example.', 31),('00326e3b-373f-4344-8cba-246e85c47682'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Convert 120° into radians (express exactly).', '2π/3', 'Using radian = (π/180)×degree, (π/180)×120° = 2π/3, as shown in the conversion relation in the excerpt.', 32),('a51a1844-2d06-423a-8b7a-59026f9842bc'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Convert 3π/4 radians into degrees.', '135°', 'Degree = (180/π) × radian so (180/π)×(3π/4)=135°, using the degree–radian formula from the excerpt.', 33),('10cd0750-a20a-4db4-8fd5-2b1d3bc292f7'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'In the circle example with arc length l = 11 cm and central angle 30°, using π = 22/7, what is the radius r (in cm)?', '21 cm', 'The excerpt computes r = l/(θ) with θ = 30° = π/6, giving r = 11 ÷ (π/6) = 11×6/π and with π = 22/7 yields r = 21 cm as shown in the worked example.', 34),('a7196963-29ca-4238-82d2-7c7c2345ce66'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'A watch minute hand of length 1.5 units moves for 40 minutes; how far does its tip move? (Use the method in the excerpt.)', '2π units', 'In 40 minutes the minute hand turns 2/3 of a revolution (θ=4π/3? the excerpt shows the result), and using l=rθ the worked example gives l = 1.5×(4π/3)=2π units, as in the example.', 35),('3f7b39ac-8ec3-4f62-8f08-3ce44b245b17'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'From the top of a 40 m vertical cliff the angle of depression to an object at ground level is 60°; how far is the object from the base of the cliff?', '40/√3 m', 'The example uses tan60° = opposite/adjacent = 40/x, so x = 40/√3, following the application worked example in the excerpt.', 36),('78e73af6-7e7d-49a0-899d-77aee3657731'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'A rope of length 20 m makes an angle of 30° with horizontal and is tied to the top of a vertical pole; what is the height of the pole?', '10 m', 'Using sin30° = opposite/hypotenuse and sin30°=1/2, the height = (1/2)×20 = 10 m, as shown in the rope example in the excerpt.', 37),('ac5eaadb-d836-4f32-8fa2-1a1ecafb6c58'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Solve 2cos θ − 1 = 0 for 0 ≤ θ < 2π. Give solutions in radians.', 'π/3 and 5π/3', 'Rewriting gives cosθ = 1/2 whose reference angle is π/3; cosine positive in quadrants I and IV yields θ = π/3 and 2π−π/3 = 5π/3, as in the trig-equation example.', 38),('7206abc3-ff72-4561-8152-d016b7928c85'::uuid, 'b1534db1-86ad-4cbd-8b6c-5dc638857c32'::uuid, 'fill_blank', 'Solve 2sin θ = −1 for 0 ≤ θ < 2π. Give solutions in radians.', '7π/6 and 11π/6', 'Rewriting sinθ = −1/2 gives reference angle π/6 and negative sine in quadrants III and IV, yielding θ = π+π/6 = 7π/6 and 2π−π/6 = 11π/6, matching the worked solution method.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
