INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'Mathematics', 'Unit 5', 'Molarum Grade 10 — Mathematics Unit 5: Circles', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 5: Circles.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('107e47a4-6056-4cde-89eb-d54c4a16c6ca'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which statement matches the definition of a circle as given in the excerpt?', 'A circle is the locus of points in a plane each equidistant from a fixed point called the center.', 'The excerpt defines a circle as the locus of points in a plane each of which is equidistant from a fixed point called the center, so the first option matches verbatim.', 0),('bc83b89c-e983-4cc5-8986-77ba156ee4d8'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which formula gives the area of a circle as stated in the excerpt?', 'A = πr^2', 'The excerpt states that the area of a circle is A = πr^2, so the first option is correct.', 1),('26cf8249-44c8-455f-8b2d-661eb0089147'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which expression equals the perimeter (circumference) of a circle according to the excerpt?', 'P = 2πr', 'The excerpt gives the perimeter of a circle as P = 2πr, so the first option is the stated formula.', 2),('fd8a0276-8a7d-408f-8238-79eae81fed37'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'According to the summary in the excerpt, which equality between radians and degrees is correct?', '2π = 360°', 'The summary states the radian-degree equivalence 2π = 360°, so that equality is correct.', 3),('1308df2d-9c30-4cfe-8bf7-36a3be2478ff'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which statement matches Theorem 5.1 as given in the excerpt?', 'The line segment joining the center of a circle to the midpoint of a chord is perpendicular to the chord.', 'Theorem 5.1 in the excerpt states exactly that the segment from the center to the chord''s midpoint is perpendicular to the chord, so the first option restates the theorem.', 4),('de8b56ef-f63f-4c44-8955-db58d1e5131f'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Theorem 5.2 in the excerpt claims which of the following about a line drawn from the center perpendicular to a chord?', 'It bisects the chord.', 'Theorem 5.2 in the excerpt proves that a line drawn from the center perpendicular to a chord bisects that chord, so the first option is correct.', 5),('b4fc25be-1f72-4f83-8c71-b9cd78270205'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which statement expresses Theorem 5.3 from the excerpt?', 'Equal chords of a circle are equidistant from the center of the circle.', 'Theorem 5.3 in the excerpt states that equal chords are equidistant from the center, so the first option paraphrases the theorem.', 6),('485cb2b2-1014-4df5-8dab-0d97cad9c8d7'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Theorem 5.4 states a relation between equal angles subtended by chords and chord lengths. Which is correct according to the excerpt?', 'If the angles subtended by the chords are equal in measure, then the lengths of the chords are equal.', 'Theorem 5.4 in the excerpt proves that equal inscribed central angles intercept equal chord lengths, so the first option states the theorem.', 7),('8f276ed0-51d6-4c46-8b5e-7309b47ed835'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which formula for the length l of a chord subtending central angle θ in a circle of radius r is given in the excerpt?', 'l = 2r sin(θ/2)', 'The excerpt gives the chord length formula l = 2r sin(θ/2) using the right triangle OAM, so the first option is the stated formula.', 8),('10e21f6a-6aac-4521-8155-8f841d7b8ee8'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which expression matches the arc length s of a circle of radius r subtended by angle θ in degrees as given in the excerpt?', 's = 2πr × (θ/360)', 'Definition 5.2 in the excerpt states the arc length s equals 2πr times θ/360, so the first option matches the formula.', 9),('d0673135-36fa-41f4-87ae-4e7f439a23e5'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which formula gives the area of a sector with radius r and central angle θ (in degrees) as shown in the excerpt?', 'Area = πr^2 × (θ/360)', 'The excerpt defines the area of a sector as πr^2 × (θ/360), so the first option is the correct sector area formula.', 10),('35155252-d6bd-43a9-85ce-a00deff4b711'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which expression equals the perimeter of a sector as stated in the excerpt?', 'Perimeter = 2r + 2πr × (θ/360)', 'The excerpt gives the perimeter of a sector as the sum of the two radii and the arc length, i.e., 2r + 2πr × (θ/360), matching the first option.', 11),('f064df45-1ac0-4807-847e-86799d386ec5'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which formula for the area A of a segment appears in the excerpt?', 'A = πr^2 × (θ/360) − 1/2 r^2 sinθ', 'The excerpt states the area of a segment equals the area of the sector minus the area of the triangle, giving A = πr^2 × (θ/360) − 1/2 r^2 sinθ, so the first option is correct.', 12),('324957cf-e862-414c-8281-9a69b26154e8'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which statement restates Theorem 5.6 from the excerpt about an inscribed angle and a central angle that intercept the same arc?', 'An inscribed angle equals half the measure of the central angle that intercepts the same arc.', 'Theorem 5.6 in the excerpt proves that an inscribed angle is half the measure of the central angle intercepting the same arc, so the first option restates the theorem.', 13),('c1d61bb5-6323-4ffa-8f07-0dc3df6fefb3'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'What does Thales'' Theorem, as stated in the excerpt, assert about an angle inscribed in a semicircle?', 'An angle inscribed in a semicircle is a right angle (90°).', 'Theorem 5.8 (Thales'' Theorem) in the excerpt states that an angle inscribed in a semicircle is a right angle, so the first option is correct.', 14),('3293010d-3205-4ffa-8080-5eba6fd87236'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which property of a cyclic quadrilateral is given as Theorem 5.9 in the excerpt?', 'The sum of a pair of opposite angles is 180°.', 'Theorem 5.9 in the excerpt shows that in a cyclic quadrilateral the sum of either pair of opposite angles equals 180°, so the first option states the theorem.', 15),('f80f657a-0402-4116-8f0d-7a3feb16cba4'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'According to Theorem 5.10 in the excerpt, the measure of an angle formed by two chords intersecting inside a circle equals which of the following?', 'One half the sum of the measures of the arcs intercepted by the angle and its vertical angle.', 'Theorem 5.10 states that an angle formed by two chords inside a circle equals one half the sum of the measures of the intercepted arcs, so the first option restates the theorem.', 16),('623042cf-877c-49de-85e9-278407b597c2'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'In the excerpt''s Example 1 (figure 5.8), a chord of length 8 cm in a circle of radius 5 cm is given. What is the distance of the chord from the center?', '3 cm', 'The example shows OM = √(OB^2 − MB^2) = √(5^2 − 4^2) = √9 = 3 cm, so the distance from the center is 3 cm.', 17),('b6dd0b84-605c-4400-8310-424e56ad2196'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'In Example 1 regarding figure 5.2 where a circle is inscribed in a square, how many lines of symmetry does the combined figure have according to the excerpt?', '4', 'The excerpt explains that a circle has infinite lines of symmetry but the inscribed circle in a square yields the combined figure having the square''s 4 lines of symmetry, so the answer is 4.', 18),('146423e9-4cf4-492c-8b77-2e9c875ce096'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'multiple_choice', 'Which of the following statements about diameters and symmetry is supported by the excerpt?', 'Any diameter of a circle can be considered as a line of symmetry for the circle.', 'The excerpt states that folding a circle over any of its diameters matches parts on each side, so any diameter can be considered a line of symmetry.', 19),('5ffa4745-4a91-4e26-8584-334121a79ee0'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'true_false', 'A major arc has measure greater than 180°.', 'True', 'The excerpt defines a major arc as an arc whose measure is greater than 180°, so the statement is True.', 20),('de879053-9cc5-4cff-829d-5039d7d1ca9d'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'true_false', 'A minor arc is usually referred to with three letters according to the excerpt.', 'False', 'The excerpt says a major arc is usually referred to with three letters while a minor arc is usually referred to with only two letters, so the statement is False.', 21),('460e8556-491c-4bdb-8f18-849c156c9e62'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'true_false', 'Coterminal angles have the same trigonometric values as stated in the excerpt.', 'True', 'The excerpt explicitly states that coterminal angles have the same trigonometric values, making the statement True.', 22),('463d0df4-520c-49b2-871b-91850950e50e'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'true_false', 'Every diameter of a circle can be considered a line of symmetry for the circle.', 'True', 'The approved Unit 5 text explains that folding a circle over any diameter makes the two sides match, so each diameter is a line of symmetry.', 23),('a8dd0875-d790-4bf2-82f0-a0cb1bd5e674'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Define a circle in one sentence using the wording from the excerpt.', 'A circle is the locus of points in a plane each of which is equidistant from a fixed point in the plane called the center.', 'This mirrors the excerpt''s definition that the circle is the locus of points equidistant from a fixed center, with that fixed distance called the radius.', 24),('18fefc02-9885-4702-8102-c70dc4eea226'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Give the perimeter (circumference) of a circle expressed using the diameter as given or implied in the excerpt.', 'P = πd', 'Since the excerpt gives P = 2πr and also uses πd in arc-length context, one may write the circumference as P = πd because d = 2r.', 25),('8ebfb48b-aaf6-4cab-8c81-18e5a0c4d8c0'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'State Theorem 5.1 from the excerpt in one sentence.', 'The line segment joining the center of a circle to the midpoint of a chord is perpendicular to the chord.', 'This is the exact statement of Theorem 5.1 in the excerpt which proves that the center-midpoint segment meets the chord at a right angle.', 26),('29b86cba-c3b9-430c-844e-c6abf1719504'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'State Theorem 5.3 (characteristic of equal chords) from the excerpt.', 'Equal chords of a circle are equidistant from the center of the circle.', 'Theorem 5.3 in the excerpt proves that equal chords are at equal distances from the center using perpendicular bisectors and congruent triangles.', 27),('189946d6-6405-4003-8238-ee4987226e75'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Write the formula for chord length l in terms of radius r and central angle θ (in degrees) as given in the excerpt.', 'l = 2r sin(θ/2)', 'The excerpt derives the chord length l = 2m = 2r sin(θ/2) using the right-angled triangle OAM and the midpoint M of the chord.', 28),('0a89da40-e2ef-4a69-8510-4cb20e997051'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Write the formula for arc length s in terms of radius r and angle θ (in degrees) as given in the excerpt.', 's = 2πr × (θ/360)', 'Definition 5.2 in the excerpt gives s = 2πr × (θ/360) (equivalently πd × (θ/360)) for the arc length subtended by angle θ.', 29),('001098b7-b6da-44e3-80d5-fc54b39a3b58'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Provide the formula for the area A of a segment in the form given in the excerpt.', 'A = πr^2 × (θ/360) − 1/2 r^2 sinθ', 'The excerpt explains that area of a segment equals area of sector minus area of the triangle, yielding A = πr^2 × (θ/360) − 1/2 r^2 sinθ.', 30),('9a9289e6-3b11-47e2-8a84-41bdd1459fa2'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'State Thales'' Theorem in one sentence as presented in the excerpt.', 'An angle inscribed in a semicircle is a right angle.', 'Theorem 5.8 in the excerpt states that an angle inscribed in a semicircle is a right angle (90°), so this one-sentence statement matches the theorem.', 31),('6aa9665c-fc64-4550-8c63-b47c9aa782a1'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Find the arc length s for a circle of radius 6 cm subtended by a central angle of 150° (use π).', '5π cm', 'Using s = 2πr × (θ/360) with r = 6 and θ = 150° gives s = 2π×6×(150/360) = 5π cm, as shown in the excerpt''s example.', 32),('91fc93ed-064a-4c1b-8ded-d1323a32b914'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'In the excerpt''s example where a chord AB = 8 cm and radius OB = 5 cm, what is the distance OM from the center to the chord?', '3 cm', 'The example computes OM = √(OB^2 − MB^2) = √(5^2 − 4^2) = √9 = 3 cm, so the distance is 3 cm.', 33),('7f108c97-d5a9-4ef8-88b5-ac3e684d6be9'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Find the chord length AB when θ = 120° and radius r = 8 cm using the chord formula from the excerpt.', '8√3 cm', 'Using l = 2r sin(θ/2): l = 2×8×sin(60°) = 16×(√3/2) = 8√3 cm, which matches the excerpt''s Example 2 result.', 34),('c69c9afd-8826-4886-8d2f-a49110532a1f'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'For a sector with radius 6 cm and angle 210°, find the area of the sector (use π) as calculated in the excerpt.', '21π cm^2', 'The excerpt computes A_sector = πr^2 × (θ/360) = π×6^2×(210/360) = 21π cm^2, so the area is 21π cm^2.', 35),('7a5dd591-61d3-4f9f-84a2-debe76f8e273'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'Using the excerpt''s example with radius 6 cm and angle 210°, find the perimeter of the sector (use π).', '12 + 7π cm', 'The excerpt finds P_sector = 2r + 2πr × (θ/360) = 2×6 + 2π×6×(210/360) = 12 + 7π cm, so that is the perimeter.', 36),('cee95757-6ec6-4376-8ec4-1299551ef0d3'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'In the excerpt''s Example 2 for a segment with r = 4 and θ = 60°, what is the area of the segment (simplified as in the excerpt)?', '3π − 4√3 m^2', 'The excerpt computes A = π·4^2×(60/360) − 1/2·4^2·sin60° = 3π − 4√3, so the area is 3π − 4√3 m^2.', 37),('7431299d-2c60-4fd4-8f9b-9dab9bf7f3fe'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'If the four angles of a cyclic quadrilateral are (4y + 2), (y + 20), (5y − 2), and 7y, what is y as solved in the excerpt?', '20', 'The excerpt sets the sum equal to 360°: (4y+2)+(y+20)+(5y−2)+7y = 360°, giving 17y+20 = 360°, so y = 340/17 = 20.', 38),('513dd311-cb62-4e8b-8d29-20c24ce74d9d'::uuid, '6c10b38d-ed75-4ad2-8e81-223722abc1eb'::uuid, 'fill_blank', 'In the excerpt''s Example 1 for intersecting chords (figure 5.55), if m(arc PQ) = 68° and m(arc RS) = 128°, what is m(∠RTS)?', '98°', 'By Theorem 5.10 the angle m(∠RTS) = 1/2 [m(arc PQ) + m(arc RS)] = 1/2 (68° + 128°) = 98°, as shown in the excerpt.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('9a8eb6df-fea9-499c-83a3-8714002fb6a2'::uuid, '107e47a4-6056-4cde-89eb-d54c4a16c6ca'::uuid, 'A circle is the locus of points in a plane each equidistant from a fixed point called the center.', TRUE, 0),('c86e1c26-2f68-4e64-8aae-a77584c4a237'::uuid, '107e47a4-6056-4cde-89eb-d54c4a16c6ca'::uuid, 'A circle is any closed curved shape with at least one axis of symmetry.', FALSE, 1),('7268db40-63e2-409e-8030-551061f1df3d'::uuid, '107e47a4-6056-4cde-89eb-d54c4a16c6ca'::uuid, 'A circle is a triangle with infinitely many sides.', FALSE, 2),('cc3f2f4b-03b6-4be7-8459-07e305b465d1'::uuid, '107e47a4-6056-4cde-89eb-d54c4a16c6ca'::uuid, 'A circle is the set of all points equidistant from any two fixed points.', FALSE, 3),('3a60ae7d-5a86-476b-8bc7-780548b525b2'::uuid, 'bc83b89c-e983-4cc5-8986-77ba156ee4d8'::uuid, 'A = πr^2', TRUE, 0),('43e29444-a247-4cde-850c-bf6bf42ad25f'::uuid, 'bc83b89c-e983-4cc5-8986-77ba156ee4d8'::uuid, 'A = 2πr', FALSE, 1),('cb01a1e3-6c13-4e9e-8341-aa78b020194e'::uuid, 'bc83b89c-e983-4cc5-8986-77ba156ee4d8'::uuid, 'A = πd', FALSE, 2),('ca23343a-0369-4908-8dfb-c4745a249e5c'::uuid, 'bc83b89c-e983-4cc5-8986-77ba156ee4d8'::uuid, 'A = 2rπ/360', FALSE, 3),('53563867-de8e-48b5-8406-36dae70bf3cf'::uuid, '26cf8249-44c8-455f-8b2d-661eb0089147'::uuid, 'P = 2πr', TRUE, 0),('c1f56acf-5c84-4290-814f-05cd339bcbd0'::uuid, '26cf8249-44c8-455f-8b2d-661eb0089147'::uuid, 'P = πr^2', FALSE, 1),('a98135f1-d7b4-48d3-824a-01352b81ded9'::uuid, '26cf8249-44c8-455f-8b2d-661eb0089147'::uuid, 'P = r^2', FALSE, 2),('78cda2b7-1753-471a-87bf-0aa64a8c8fd8'::uuid, '26cf8249-44c8-455f-8b2d-661eb0089147'::uuid, 'P = 360° × r', FALSE, 3),('2899b68c-2d87-488d-88c0-4110466220be'::uuid, 'fd8a0276-8a7d-408f-8238-79eae81fed37'::uuid, '2π = 360°', TRUE, 0),('e38aa4d6-f584-4aee-8e3c-0c06ae38e73f'::uuid, 'fd8a0276-8a7d-408f-8238-79eae81fed37'::uuid, 'π = 360°', FALSE, 1),('993c8c10-6c2d-48c8-8fc8-d26020b97b35'::uuid, 'fd8a0276-8a7d-408f-8238-79eae81fed37'::uuid, 'π/2 = 360°', FALSE, 2),('0da1ed8f-7736-4400-8ebc-37a3f1cb9659'::uuid, 'fd8a0276-8a7d-408f-8238-79eae81fed37'::uuid, '360° = 1°', FALSE, 3),('e31acaf2-5708-431c-80a2-f6da06ea071c'::uuid, '1308df2d-9c30-4cfe-8bf7-36a3be2478ff'::uuid, 'The line segment joining the center of a circle to the midpoint of a chord is perpendicular to the chord.', TRUE, 0),('a4f60121-f5fe-4466-822a-2b21088f996c'::uuid, '1308df2d-9c30-4cfe-8bf7-36a3be2478ff'::uuid, 'Every radius is parallel to every chord in the circle.', FALSE, 1),('6d8e5012-d2f7-47d4-8a61-aaaa08f39365'::uuid, '1308df2d-9c30-4cfe-8bf7-36a3be2478ff'::uuid, 'A chord is always longer than the diameter.', FALSE, 2),('523a5a73-5ab7-47a1-8144-e1215162ffbb'::uuid, '1308df2d-9c30-4cfe-8bf7-36a3be2478ff'::uuid, 'The midpoint of any chord coincides with the center of the circle.', FALSE, 3),('dbf870a7-e446-4478-80ec-6ff708b7ef8b'::uuid, 'de8b56ef-f63f-4c44-8955-db58d1e5131f'::uuid, 'It bisects the chord.', TRUE, 0),('0ee402d1-987c-4a79-8ec7-5e738521b9f5'::uuid, 'de8b56ef-f63f-4c44-8955-db58d1e5131f'::uuid, 'It doubles the chord length.', FALSE, 1),('5cf5799a-c500-4e40-8119-22c0b5c2fd90'::uuid, 'de8b56ef-f63f-4c44-8955-db58d1e5131f'::uuid, 'It is equal to the chord.', FALSE, 2),('6c523f96-5e58-486e-8f6e-261443ced28e'::uuid, 'de8b56ef-f63f-4c44-8955-db58d1e5131f'::uuid, 'It is parallel to the chord.', FALSE, 3),('808a3f2a-5a01-40ef-8d01-ea38a81f2f6d'::uuid, 'b4fc25be-1f72-4f83-8c71-b9cd78270205'::uuid, 'Equal chords of a circle are equidistant from the center of the circle.', TRUE, 0),('66549fdd-ded2-4a02-8df5-35c3f41cb7e3'::uuid, 'b4fc25be-1f72-4f83-8c71-b9cd78270205'::uuid, 'Chords that are equidistant from the center are unequal in length.', FALSE, 1),('0b9596b8-4e14-4719-8929-d1b59675b8cc'::uuid, 'b4fc25be-1f72-4f83-8c71-b9cd78270205'::uuid, 'Equal chords always subtend right angles at the center.', FALSE, 2),('c149846c-ff78-45a2-881e-72391e88601f'::uuid, 'b4fc25be-1f72-4f83-8c71-b9cd78270205'::uuid, 'Equal chords must lie on the same diameter.', FALSE, 3),('b8d9774d-9115-4b4c-8746-3a133d8c80c9'::uuid, '485cb2b2-1014-4df5-8dab-0d97cad9c8d7'::uuid, 'If the angles subtended by the chords are equal in measure, then the lengths of the chords are equal.', TRUE, 0),('67b3e920-8ee1-488a-873d-4a1b128a40ff'::uuid, '485cb2b2-1014-4df5-8dab-0d97cad9c8d7'::uuid, 'If chords are equal in length, their subtended angles are always different.', FALSE, 1),('63ff5c41-7a1a-4ac2-8652-1b39d22f3bd1'::uuid, '485cb2b2-1014-4df5-8dab-0d97cad9c8d7'::uuid, 'Equal subtended angles imply the chords are perpendicular to the radius.', FALSE, 2),('3f3d972b-8364-4a98-80a7-28e8da87cc43'::uuid, '485cb2b2-1014-4df5-8dab-0d97cad9c8d7'::uuid, 'Equal subtended angles imply the arcs have zero measure.', FALSE, 3),('f1cbd188-b601-4fbc-8c28-9e96982f01c1'::uuid, '8f276ed0-51d6-4c46-8b5e-7309b47ed835'::uuid, 'l = 2r sin(θ/2)', TRUE, 0),('3bbdab73-a0f3-41b6-8552-46f965e13468'::uuid, '8f276ed0-51d6-4c46-8b5e-7309b47ed835'::uuid, 'l = πrθ', FALSE, 1),('61269dd9-71c3-4875-82c2-2fbbaabca050'::uuid, '8f276ed0-51d6-4c46-8b5e-7309b47ed835'::uuid, 'l = rθ/360', FALSE, 2),('cfd27c0d-6aa3-4370-8bd6-b865e1db8569'::uuid, '8f276ed0-51d6-4c46-8b5e-7309b47ed835'::uuid, 'l = r^2 + θ', FALSE, 3),('cb9eb084-fe04-404c-8ef3-c82743f13bbc'::uuid, '10e21f6a-6aac-4521-8155-8f841d7b8ee8'::uuid, 's = 2πr × (θ/360)', TRUE, 0),('e590d5e7-e77f-4f4f-8135-02951f0cf295'::uuid, '10e21f6a-6aac-4521-8155-8f841d7b8ee8'::uuid, 's = πr^2 × (θ/360)', FALSE, 1),('47cb09d8-3e2d-4106-82b6-e86da93015c8'::uuid, '10e21f6a-6aac-4521-8155-8f841d7b8ee8'::uuid, 's = 2r × θ', FALSE, 2),('c697388b-5019-45b4-82df-004c917a15bf'::uuid, '10e21f6a-6aac-4521-8155-8f841d7b8ee8'::uuid, 's = r × sin(θ)', FALSE, 3),('7aa82b0f-d031-47c1-8e3d-2b42fdacb529'::uuid, 'd0673135-36fa-41f4-87ae-4e7f439a23e5'::uuid, 'Area = πr^2 × (θ/360)', TRUE, 0),('68a75344-dc86-48b6-8a86-35095543c6e2'::uuid, 'd0673135-36fa-41f4-87ae-4e7f439a23e5'::uuid, 'Area = 2πr × (θ/360)', FALSE, 1),('8243b301-8253-4ac5-8895-8417beba51e8'::uuid, 'd0673135-36fa-41f4-87ae-4e7f439a23e5'::uuid, 'Area = 2r + 2πr × (θ/360)', FALSE, 2),('92327127-5df1-4fe5-8be2-d8dd685f390c'::uuid, 'd0673135-36fa-41f4-87ae-4e7f439a23e5'::uuid, 'Area = rθ', FALSE, 3),('1a336532-1723-4ba2-8ff5-9b9a7a89ff06'::uuid, '35155252-d6bd-43a9-85ce-a00deff4b711'::uuid, 'Perimeter = 2r + 2πr × (θ/360)', TRUE, 0),('5838ca90-2a1d-4389-8d3a-5d8041adb195'::uuid, '35155252-d6bd-43a9-85ce-a00deff4b711'::uuid, 'Perimeter = πr^2 × (θ/360)', FALSE, 1),('36cd3622-54bc-4d48-89af-c32beef0fad9'::uuid, '35155252-d6bd-43a9-85ce-a00deff4b711'::uuid, 'Perimeter = 2πr', FALSE, 2),('d56b4fc0-9eae-4856-8c03-d6904ca51ab8'::uuid, '35155252-d6bd-43a9-85ce-a00deff4b711'::uuid, 'Perimeter = r + θ', FALSE, 3),('f7cabcb2-2da4-4f28-82f8-db5e10e39698'::uuid, 'f064df45-1ac0-4807-847e-86799d386ec5'::uuid, 'A = πr^2 × (θ/360) − 1/2 r^2 sinθ', TRUE, 0),('6a9adf09-14a7-4045-8a0b-473210ff332d'::uuid, 'f064df45-1ac0-4807-847e-86799d386ec5'::uuid, 'A = 2πr × (θ/360) − r', FALSE, 1),('b8348148-6776-4dbc-8ef2-5bc583d4b3bf'::uuid, 'f064df45-1ac0-4807-847e-86799d386ec5'::uuid, 'A = πr^2 + 1/2 r^2 sinθ', FALSE, 2),('636e8c40-1c86-4c7b-8f70-bd077fd58828'::uuid, 'f064df45-1ac0-4807-847e-86799d386ec5'::uuid, 'A = rθ − πr^2', FALSE, 3),('779955d6-5a4c-4d2b-80f9-b605460eabba'::uuid, '324957cf-e862-414c-8281-9a69b26154e8'::uuid, 'An inscribed angle equals half the measure of the central angle that intercepts the same arc.', TRUE, 0),('1ea9378d-9bca-44b8-8d10-2ccfef1acd81'::uuid, '324957cf-e862-414c-8281-9a69b26154e8'::uuid, 'An inscribed angle equals twice the central angle intercepting the same arc.', FALSE, 1),('710f866a-90c4-410c-80c1-4da48dc36c98'::uuid, '324957cf-e862-414c-8281-9a69b26154e8'::uuid, 'An inscribed angle and the central angle are always equal in measure.', FALSE, 2),('2e36e286-7232-4663-8f23-eab015ee5f32'::uuid, '324957cf-e862-414c-8281-9a69b26154e8'::uuid, 'An inscribed angle is unrelated to the central angle intercepting the same arc.', FALSE, 3),('aa1c1d98-8062-45eb-83b4-192051b82f81'::uuid, 'c1d61bb5-6323-4ffa-8f07-0dc3df6fefb3'::uuid, 'An angle inscribed in a semicircle is a right angle (90°).', TRUE, 0),('b5c5505a-ede0-4978-851e-e800169ccba5'::uuid, 'c1d61bb5-6323-4ffa-8f07-0dc3df6fefb3'::uuid, 'An angle inscribed in a semicircle is 60°.', FALSE, 1),('76e1c688-0f7f-4338-83a3-d092dfdf92d3'::uuid, 'c1d61bb5-6323-4ffa-8f07-0dc3df6fefb3'::uuid, 'An angle inscribed in a semicircle is equal to the central angle.', FALSE, 2),('a5d71105-3e91-4a48-8a06-2f77a2aa2c0f'::uuid, 'c1d61bb5-6323-4ffa-8f07-0dc3df6fefb3'::uuid, 'An angle inscribed in a semicircle is always obtuse.', FALSE, 3),('9ff372c5-7336-4846-81e8-d534664cdd07'::uuid, '3293010d-3205-4ffa-8080-5eba6fd87236'::uuid, 'The sum of a pair of opposite angles is 180°.', TRUE, 0),('1831740f-e248-476d-82b3-f87abd573775'::uuid, '3293010d-3205-4ffa-8080-5eba6fd87236'::uuid, 'All four angles are equal.', FALSE, 1),('3b34c900-ee30-4b71-8975-7bd54554bfd6'::uuid, '3293010d-3205-4ffa-8080-5eba6fd87236'::uuid, 'The product of opposite sides is constant.', FALSE, 2),('f039aa40-0bb7-4046-8003-9912c9b88b26'::uuid, '3293010d-3205-4ffa-8080-5eba6fd87236'::uuid, 'Opposite angles are supplementary only if the quadrilateral is a square.', FALSE, 3),('6ac0d91b-f9a1-457e-80f2-e76d89330a58'::uuid, 'f80f657a-0402-4116-8f0d-7a3feb16cba4'::uuid, 'One half the sum of the measures of the arcs intercepted by the angle and its vertical angle.', TRUE, 0),('dbb96ef2-3223-4777-85db-47440d036fb6'::uuid, 'f80f657a-0402-4116-8f0d-7a3feb16cba4'::uuid, 'The difference of the intercepted arcs without any factor.', FALSE, 1),('b3ece438-82b5-4735-8d27-bbdf373dba43'::uuid, 'f80f657a-0402-4116-8f0d-7a3feb16cba4'::uuid, 'Twice the measure of one intercepted arc.', FALSE, 2),('2cc2cf48-23af-4cb9-80ba-a8dc5f223406'::uuid, 'f80f657a-0402-4116-8f0d-7a3feb16cba4'::uuid, 'The product of the intercepted arcs divided by two.', FALSE, 3),('a2980575-b166-45dc-8ecf-9c8ae0fcef8e'::uuid, '623042cf-877c-49de-85e9-278407b597c2'::uuid, '3 cm', TRUE, 0),('0c546402-8675-403d-8e04-8e702600a9be'::uuid, '623042cf-877c-49de-85e9-278407b597c2'::uuid, '4 cm', FALSE, 1),('cebf0bd4-32d5-4bd5-826a-09e2f62c535f'::uuid, '623042cf-877c-49de-85e9-278407b597c2'::uuid, '√9 cm', FALSE, 2),('cfe50952-c5c2-4a71-8246-0d9dec008461'::uuid, '623042cf-877c-49de-85e9-278407b597c2'::uuid, '1 cm', FALSE, 3),('66caf8fa-3513-4a8f-8173-ba69bed57db4'::uuid, 'b6dd0b84-605c-4400-8310-424e56ad2196'::uuid, '4', TRUE, 0),('9424c541-658c-48e5-8926-ffe887df3b97'::uuid, 'b6dd0b84-605c-4400-8310-424e56ad2196'::uuid, 'Infinite', FALSE, 1),('325c35fc-68b8-49f1-84ae-c13da036fa06'::uuid, 'b6dd0b84-605c-4400-8310-424e56ad2196'::uuid, '8', FALSE, 2),('bb82dcf1-4407-4c26-8edd-6d40e0c9d9dc'::uuid, 'b6dd0b84-605c-4400-8310-424e56ad2196'::uuid, '1', FALSE, 3),('f0def9b8-879e-46e0-856e-227232b4af95'::uuid, '146423e9-4cf4-492c-8b77-2e9c875ce096'::uuid, 'Any diameter of a circle can be considered as a line of symmetry for the circle.', TRUE, 0),('821c0c2b-9ba9-49e6-8648-edea11c30939'::uuid, '146423e9-4cf4-492c-8b77-2e9c875ce096'::uuid, 'Only one specific diameter can be a line of symmetry.', FALSE, 1),('d8ed6982-b418-4a5a-8b0d-5411443f7ee5'::uuid, '146423e9-4cf4-492c-8b77-2e9c875ce096'::uuid, 'Diameters are never lines of symmetry.', FALSE, 2),('db39c8d6-34aa-46a4-86fa-06fe765a9a66'::uuid, '146423e9-4cf4-492c-8b77-2e9c875ce096'::uuid, 'A diameter is a line of symmetry only if it passes through a vertex.', FALSE, 3),('80b29397-d001-4e41-84d7-864bd4a2685e'::uuid, '5ffa4745-4a91-4e26-8584-334121a79ee0'::uuid, 'True', TRUE, 0),('f539f0da-10a8-4b90-8c22-4d92b638a007'::uuid, '5ffa4745-4a91-4e26-8584-334121a79ee0'::uuid, 'False', FALSE, 1),('46124536-5811-4067-8825-d66ba0db4cb8'::uuid, 'de879053-9cc5-4cff-829d-5039d7d1ca9d'::uuid, 'True', FALSE, 0),('38c246a3-69bc-4ab7-8138-6ea27bbb137a'::uuid, 'de879053-9cc5-4cff-829d-5039d7d1ca9d'::uuid, 'False', TRUE, 1),('3071932d-188d-4bf6-8843-51f86ffa2627'::uuid, '460e8556-491c-4bdb-8f18-849c156c9e62'::uuid, 'True', TRUE, 0),('4597e1cf-4740-4fb5-8fed-0db8b1fe0b76'::uuid, '460e8556-491c-4bdb-8f18-849c156c9e62'::uuid, 'False', FALSE, 1),('76b5934a-ad3b-4af7-8f8d-39e3eb280014'::uuid, '463d0df4-520c-49b2-871b-91850950e50e'::uuid, 'True', TRUE, 0),('e3deec88-6167-4bc5-8ae6-fb85fe0ae89d'::uuid, '463d0df4-520c-49b2-871b-91850950e50e'::uuid, 'False', FALSE, 1) ON CONFLICT (id) DO UPDATE SET question_id = EXCLUDED.question_id, choice_text = EXCLUDED.choice_text, is_correct = EXCLUDED.is_correct, order_index = EXCLUDED.order_index;
INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'Mathematics', 'Unit 6', 'Molarum Grade 10 — Mathematics Unit 6: Solid Figures', 'Source-grounded Molarum Grade 10 Mathematics questions for Unit 6: Solid Figures.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('187d9bee-646d-4439-834f-624f7d9c625f'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which formula gives the lateral surface area (LSA) of a right prism as stated in the excerpt?', 'LSA = p h', 'The excerpt states LSA = p h where p is the perimeter of the base and h is the altitude of the prism, so LSA = p h is the correct formula.', 0),('e5672279-5ec3-4bdc-83e4-9c7ad83d6ccf'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'According to the excerpt, which expression equals the volume V of any prism?', 'V = BA · h', 'The excerpt states the volume of any prism equals the product of its base area BA and altitude h, so V = BA · h.', 1),('d3b6796e-d74b-49a5-8a3d-25e5faaf96ea'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which formula in the excerpt is the lateral surface area of a right circular cylinder?', 'LSA = 2π r h', 'The excerpt gives the lateral surface area of a right circular cylinder as LSA = 2π r h, where r is base radius and h is altitude.', 2),('b37105c9-02af-4392-8922-0c564cca2d29'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which expression is given in the excerpt for the total surface area (TSA) of a right circular cylinder?', 'TSA = 2π r (h + r)', 'The excerpt states TSA = 2π r h + 2π r^2 and simplifies this as TSA = 2π r (h + r), so TSA = 2π r (h + r) is correct.', 3),('4b682d81-1105-4829-8999-e25bd1914987'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'What is the formula for the volume of a circular cylinder as stated in the excerpt?', 'V = π r^2 h', 'The excerpt gives the cylinder volume formula V = BA · h and BA = π r^2, so V = π r^2 h is the stated formula.', 4),('60c7a29c-71b2-43a6-8f37-89c912ac427c'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'According to the excerpt, which formula gives the lateral surface area (LSA) of a right circular cone?', 'LSA = π r l', 'The excerpt shows that flattening the cone gives a sector with area π r l, so the lateral surface area of a right circular cone is LSA = π r l.', 5),('472e7519-be18-4546-8dd6-e2f44d80e2b2'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which expression for the slant height l of a right circular cone is given in the excerpt?', 'l = √(h^2 + r^2)', 'The excerpt states the slant height of a right circular cone is l = √(h^2 + r^2), where h is the altitude and r the base radius.', 6),('935953b1-5980-4654-802d-b29668ebaa8c'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'What is the total surface area (TSA) of a right circular cone as given in the excerpt?', 'TSA = π r (l + r)', 'The excerpt defines TSA for a cone as the sum of base area and lateral area, TSA = π r l + π r^2 = π r (l + r).', 7),('79e66582-5095-43c5-8255-ad41403812b1'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'For a regular pyramid, which formula for the lateral surface area (LSA) is given in the excerpt?', 'LSA = 1/2 p l', 'The excerpt generalizes that the LSA of a regular pyramid equals half the product of its base perimeter p and slant height l, LSA = 1/2 p l.', 8),('7b85492a-f378-44a1-8c5e-f6110feb3040'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which expression does the excerpt give for the total surface area (TSA) of a regular pyramid?', 'TSA = BA + 1/2 p l', 'The excerpt states the total surface area of a regular pyramid is TSA = BA + LSA and with LSA = 1/2 p l gives TSA = BA + 1/2 p l.', 9),('98f90f81-21fe-4861-8102-86f61a67c073'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'What is the volume formula for any pyramid stated in the excerpt?', 'V = 1/3 BA · h', 'The excerpt proves and states the volume of a pyramid is one third of the product of its base area and altitude, V = 1/3 BA · h.', 10),('417aabe9-6f33-42dd-86be-d0d17b99b843'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which formula for the volume of a circular cone appears in the excerpt?', 'V = 1/3 π r^2 h', 'The excerpt gives Theorem 6.8 which states the volume of a circular cone is V = 1/3 π r^2 h.', 11),('8d10b2ac-5065-4662-857c-8d6c5e34c5a2'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'The lateral surface area of a frustum of a right circular cone with slant height l and base radii r and r′ is given in the excerpt as:', 'LSA = π l (r + r′)', 'The excerpt derives and states the lateral surface area of a frustum of a right circular cone as LSA = π l (r + r′).', 12),('22535125-a4d8-4833-84c4-cb529054a9bb'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'According to the excerpt, the total surface area (TSA) of a frustum of a right circular cone equals which expression?', 'TSA = π l (r + r′) + π(r^2 + r′^2)', 'The excerpt computes LSA = π l (r + r′) and base areas π r^2 and π r′^2, giving TSA = π l (r + r′) + π(r^2 + r′^2).', 13),('145583b9-e0e8-4abb-82dd-6e5a2c2460e6'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Theorem 6.2 states the ratio of the area of a horizontal cross-section at distance k from the vertex to the area of the base equals which of the following?', 'k^2 / h^2', 'Theorem 6.2 in the excerpt shows area(cross-section)/area(base) = k^2 / h^2, where h is the altitude and k the distance from the vertex to the cross-section.', 14),('080c2c76-c26c-4b3e-896b-bfcd199a5ea1'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'From the similarity argument in the excerpt, the ratio of corresponding side lengths of a horizontal cross-section triangle to the base triangle equals which quantity?', 'k / h', 'The proof of Theorem 6.1 shows corresponding sides are proportional with ratio equal to k / h, where k is distance from vertex to cross-section and h is altitude.', 15),('2f5cc3c5-7fb1-4f09-8c17-e6b7f63984a1'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which formula for the surface area (SA) of a sphere is given in the excerpt?', 'SA = 4π r^2', 'The excerpt states that if r is the radius of a sphere then SA = 4π r^2, which is the surface area formula given.', 16),('d67e1136-edd9-40a2-81df-d3251eb9faa7'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'What volume formula for a sphere appears in the excerpt?', 'V = 4/3 π r^3', 'The excerpt gives the sphere volume as V = 4/3 π r^3 where r is the radius of the sphere.', 17),('4b9a3f47-437a-4f3c-8f69-7a6ffd261132'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'In the net of a regular pentagonal pyramid in the excerpt, what is the area of one lateral face ΔVED expressed as?', '1/2 s l', 'The excerpt shows each lateral face is an isosceles triangle with area area(ΔVED) = 1/2 s l, where s is a side of the base and l the slant height.', 18),('63acc90c-ff40-4a3c-8595-303f245ec5a2'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'multiple_choice', 'Which statement matches Cavalieri''s Principle as given in the excerpt?', 'If two solids of equal height have equal cross-sectional areas at every level parallel to the bases, then the two solids have equal volume.', 'The excerpt states Cavalieri''s Principle as exactly that: equal height and equal cross-sectional areas at every parallel level imply equal volumes.', 19),('6188fb17-119c-4efa-8cbf-f44fd87b5b7f'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'true_false', 'The lateral surface area of a right circular cone equals π r l as given in the excerpt.', 'True', 'The excerpt derives the lateral surface area of a right circular cone and states LSA = π r l, so the statement is True.', 20),('837dcc87-403d-45da-8503-b827455c8bde'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'true_false', 'The formula π r^2 h is the lateral surface area of a right circular cylinder as given in the excerpt.', 'False', 'The excerpt gives LSA of a cylinder as 2π r h and π r^2 h is the volume formula, so the statement is False.', 21),('b4dcf5c3-9c74-447d-8b98-930b85ffbf86'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'true_false', 'A hemisphere is one of the two equal parts into which a sphere is divided by a great circle, as stated in the excerpt.', 'True', 'The excerpt defines a hemisphere as one of the two equal parts of a sphere divided by a great circle, so the statement is True.', 22),('f100a9cc-f05d-4c4c-8185-928381dbdd6f'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'true_false', 'The lateral faces of a frustum of a pyramid are trapeziums, as observed in the excerpt.', 'True', 'In the observations the excerpt explicitly states that the lateral faces of a frustum of a pyramid are trapezium, so this is True.', 23),('5c28fd3d-a695-4cb7-816e-2d0bb618c48f'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Define the slant height of a cone as given in the excerpt.', 'The line segment from the vertex to a point on the boundary of the base circle; it is the length of a generatrix of the cone.', 'The excerpt defines the slant height as the line segment from the vertex to a point on the base circle and notes this segment forms the lateral surface when rotated.', 24),('b273129d-6f30-48f5-89e0-3ebc745a2956'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'State the formula for the volume of a sphere from the excerpt.', 'V = 4/3 π r^3', 'The excerpt gives the volume of a sphere as V = 4/3 π r^3 where r is the radius of the sphere.', 25),('54ebfaee-7f2b-474f-8c13-6ba22f8e0077'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'State the formula for the surface area of a sphere as presented in the excerpt.', 'SA = 4π r^2', 'The excerpt states that if r is the radius of a sphere then its surface area is SA = 4π r^2.', 26),('e3caf423-1cfa-46f2-8ab2-754855c50d9d'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Give the lateral surface area formula for a regular pyramid in terms of perimeter p and slant height l as in the excerpt.', 'LSA = 1/2 p l', 'The excerpt generalizes that for a regular pyramid LSA equals half the product of the base perimeter p and slant height l, namely LSA = 1/2 p l.', 27),('4b45616e-16af-43ac-8e11-300fbdb613bb'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'What is a geometry net according to Definition 6.3 in the excerpt?', 'A two-dimensional shape that can be folded to form a three-dimensional solid, showing each face of the figure when laid flat.', 'Definition 6.3 in the excerpt defines a net as a 2D pattern that can be folded to form the corresponding 3D solid, showing every face.', 28),('9d34f219-d83b-4143-8f75-56315d0fe99c'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Give the formula for the length l of an arc that subtends angle θ at the center of a circle with radius r as in the excerpt.', 'l = 2π r × (θ / 360)', 'Summary item 13 in the excerpt gives the arc length formula l = 2π r × θ/360 for central angle θ in degrees and radius r.', 29),('253a732f-bf39-48fb-850f-34c1bb8928b3'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'State Cavalieri''s Principle as given in the excerpt in one sentence.', 'If two solids of equal height have equal cross-sectional areas at every level parallel to the bases, then the two solids have equal volume.', 'The excerpt states Cavalieri''s Principle exactly as: equal-height solids with equal parallel cross-sectional areas at every level have equal volumes.', 30),('bc464731-ad34-4990-897b-7d18a8789aa4'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Write the volume formula for a frustum of a right circular cone given in the excerpt.', 'V = 1/3 π h (r^2 + r′^2 + r r′)', 'The excerpt derives and gives the frustum volume formula V = 1/3 π h (r^2 + r′^2 + r r′), where r and r′ are the radii of the bases and h the altitude.', 31),('7686c5c2-a212-4b3c-82fc-c29437031f7f'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Example 1 for prisms: A right triangular prism has base triangle with legs 3 cm and 4 cm and altitude 6 cm; what is its volume (in cm^3) as computed in the excerpt?', '36 cm3', 'The excerpt computes BA = 1/2·3·4 = 6 cm^2 and V = BA·h = 6·6 = 36 cm^3, so the volume is 36 cm^3.', 32),('61427663-eecb-4edc-8211-df680fcd1c31'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'From Example 4 (cylinder): A right circular cylinder has radius 3 cm and altitude 5 cm. What is its total surface area (TSA) as given in the excerpt? Express your answer using π.', '48π cm2', 'The excerpt computes TSA = 2π r (h + r) = (2π·3)(5+3) = 48π cm^2, so TSA = 48π cm^2.', 33),('2afab4e3-7714-4f19-8866-610b1b83da6a'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'From Example 4 (cone): A right circular cone has base diameter 8 cm and height 3 cm. What is its lateral surface area (LSA) as shown in the excerpt? Express using π.', '20π cm2', 'The excerpt finds r = 4 cm, l = √(3^2+4^2)=5 cm, then LSA = π r l = π·4·5 = 20π cm^2.', 34),('fb9cf901-e8ea-4666-802e-488baf7328be'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'In Example 2 for frustum: A right circular cone of altitude 8 cm and base radius 6 cm is cut to form a frustum of height 4 cm. What is the lateral surface area of the frustum as computed in the excerpt? Express using π.', '45π cm2', 'The excerpt computes small cone r′=3 and slant heights l=10, l′=5, so LSA(frustum)=LSA(big)−LSA(small)=60π−15π=45π cm^2.', 35),('a2bfbdaa-d666-4c01-8a71-423bd6cef45f'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'From Example 3: A frustum of a right circular cone has slant height 26 cm, base radii 22 cm and 12 cm; what is its total surface area (TSA) in terms of π as given in the excerpt?', '1512π cm2', 'The excerpt finds LSA = 26π(22+12)=884π and BA = π(22^2+12^2)=628π, giving TSA = 884π+628π = 1512π cm^2.', 36),('81449ea7-c1a1-4b6b-89f5-13769235410d'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Example 4 computes the volume of a frustum whose top and bottom diameters are 6 m and 10 m and height 12 m. What is the volume in cubic metres as given in the excerpt (use the numeric value shown)?', '615.44 m3', 'The excerpt computes r=3, r′=5 and V = 1/3 π·12(3^2+5^2+3·5)=196π ≈ 196×3.14 = 615.44 m^3, so the volume is 615.44 m^3.', 37),('0294dc63-b53e-4170-8f0b-468fcc36e0bf'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'Using the sphere formula given in the excerpt, what is the surface area of a sphere of radius 10 cm? Express using π.', '400π cm2', 'Using SA = 4π r^2 from the excerpt and r = 10 cm gives SA = 4π·10^2 = 400π cm^2.', 38),('0061a356-7d34-4251-8e90-d940870933c4'::uuid, 'a5380021-8ffd-4711-8030-9605e75b6db4'::uuid, 'fill_blank', 'In Example 2 (composed solid): A solid made of a cone of altitude 3 cm on top of a cylinder of radius 4 cm has overall height 10 cm. What is the total volume of the solid as given in the excerpt (express using π)?', '128π cm3', 'The excerpt computes cylinder volume π·4^2·7 = 112π and cone volume 1/3 π·4^2·3 = 16π, so total = 112π+16π = 128π cm^3.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
